const e="hsk",t=3,n=[{num:1,title:"周末你有什么打算",points:[{id:"3.1.1",name:"结果补语“好”：V + 好",pinyin:"jiéguǒ bǔyǔ “hǎo”",type:"结果补语",explainEn:"Use V + 好 to mean the action is finished and ready.",structure:"动词 + 好",examples:[{zh:"饭做好了。",en:"The food is ready.",py:"Fàn zuò hǎo le."},{zh:"我的作业写好了。",en:"My homework is finished.",py:"Wǒ de zuòyè xiě hǎo le."},{zh:"东西都准备好了。",en:"Everything is ready.",py:"Dōngxi dōu zhǔnbèi hǎo le."}],exercises:[{kind:"choice",q:"要照相了，大家坐___，看这儿！",instr:"辨析",instrEn:"Pick the right one",body:"要照相了，大家坐___，看这儿！",options:["完","好","到","对"],answer:1,explain:"“坐好”表示坐得端正、准备好了；“坐完”说动作做完，没有这个意思，“坐到”后面要说地点，“坐对”也不这样说。",explainEn:'坐好 means sitting properly and ready; 坐完 means "finished sitting", 坐到 needs a place after it, and 坐对 is not said here.'},{kind:"choice",q:"我们说好了明天一起去爬山，___",instr:"完成",instrEn:"Complete the sentence",body:"我们说好了明天一起去爬山，___",options:["你可别忘记了。","可是我们还没决定。","所以他明天不会去了。","他还没告诉我去不去。"],answer:0,explain:"“说好了”表示已经商量好、定下来了，所以提醒对方别忘记；“还没决定、还没告诉我”都说明还没说好。",explainEn:'说好了 means it has been agreed and settled, so the speaker reminds the other not to forget; "not decided yet" means nothing was agreed.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["衣服我洗好了。","我的作业写了好。","你准备好了吗？","菜还没做好。"],answer:1,explain:"“好”要紧跟在动词后面，“了”放在“好”后面，应说“我的作业写好了”。",explainEn:"好 must come right after the verb, with 了 after it: 我的作业写好了."},{q:"翻译：The tickets are bought. Let us go.",a:"票买好了，我们走吧。",instr:"翻译",instrEn:"Translate",body:"The tickets are bought. Let us go."}],note:"“好”表示动作完成，并常有“已经准备好”的意思。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"Verb + hǎo = finish doing sth (done properly)",noteEn:'好 marks completion, often with the sense of "ready/done well".',typeEn:"Result complement"},{id:"3.1.2",name:"“一……也/都 + 不/没……”表示完全否定",pinyin:"yī ... yě/dōu + bù/méi",type:"否定结构",explainEn:"Use 一…也/都不/没… to mean “not even one / not at all”.",structure:"一 + 量词 + 名词 + 也/都 + 不/没 + 动词",examples:[{zh:"我一个苹果也没吃。",en:"I did not eat even one apple.",py:"Wǒ yí ge píngguǒ yě méi chī."},{zh:"今天我一点儿也不累。",en:"I am not tired at all today.",py:"Jīntiān wǒ yìdiǎnr yě bú lèi."},{zh:"他一句话都没说。",en:"He did not say a single word.",py:"Tā yí jù huà dōu méi shuō."}],exercises:[{kind:"choice",q:"这个电影我一次也___看过。",instr:"辨析",instrEn:"Pick the right one",body:"这个电影我一次也___看过。",options:["不","别","没","不会"],answer:2,explain:"说过去的经历用“没……过”，所以是“一次也没看过”；“不、不会、别”都不能和“过”一起表示没有过的经历。",explainEn:"For past experience use 没…过: 一次也没看过; 不, 不会 and 别 cannot negate an experience with 过."},{kind:"choice",q:"我一点儿也不饿，___",instr:"完成",instrEn:"Complete the sentence",body:"我一点儿也不饿，___",options:["我想吃一点儿面条。","你们吃吧，我不吃了。","我们快点儿去吃饭吧。","你给我做点儿饭吧。"],answer:1,explain:"“一点儿也不饿”是完全不饿，所以不吃了；不要把它理解成“有一点儿饿”，所以不会想吃东西。",explainEn:'一点儿也不饿 means not hungry at all, so the speaker will not eat; it does not mean "a little hungry".'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我一本书也看了。","我一个人也不认识。","他一口水也没喝。","我一点儿也不想去。"],answer:0,explain:"“一……也/都……”后面要用否定，应说“我一本书也没看”。",explainEn:"一…也/都… must be followed by a negative: 我一本书也没看."},{q:"翻译：I did not buy a single thing today.",a:"今天我一件东西也没买。",instr:"翻译",instrEn:"Translate",body:"I did not buy a single thing today."}],note:"“不”多否定习惯/现在；“没”多否定已经发生的动作。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"yī + measure word + Noun + yě/dōu + bù/méi + Verb = not even one …",noteEn:"不 negates habits/present states; 没 negates actions that have (not) happened.",typeEn:"Negation"},{id:"3.1.3",name:"连词“那”表示“那么/既然这样”",pinyin:"nà",type:"连词",explainEn:"Use 那 at the start of a reply to mean “then / in that case”.",structure:"那 + 句子",examples:[{zh:"你累了？那休息一下吧。",en:"You are tired? Then take a rest.",py:"Nǐ lèi le? Nà xiūxi yíxià ba."},{zh:"明天下雨？那我们不去了。",en:"It will rain tomorrow? Then we will not go.",py:"Míngtiān xià yǔ? Nà wǒmen bú qù le."},{zh:"你没时间？那下次再见。",en:"You have no time? Then see you next time.",py:"Nǐ méi shíjiān? Nà xià cì zàijiàn."}],exercises:[{kind:"choice",q:"电影票没有了？___我们明天再来吧。",instr:"辨析",instrEn:"Pick the right one",body:"电影票没有了？___我们明天再来吧。",options:["但是","那","因为","而且"],answer:1,explain:"“那”接着对方的话，表示“既然这样”，后面说打算；“但是、因为、而且”不能这样接对方的话。",explainEn:"那 picks up what was just said: “in that case…”. 但是, 因为 and 而且 do not start a reply this way."},{kind:"choice",q:"你不想吃米饭？那___",instr:"完成",instrEn:"Complete the sentence",body:"你不想吃米饭？那___",options:["米饭是我做的。","我们吃面条吧。","我昨天吃了米饭。","米饭很便宜。"],answer:1,explain:"“那”接着对方的话，后面要说根据这个情况作出的决定或建议：不想吃米饭，就换面条；其他几句只是说情况，不是决定。",explainEn:"那 picks up what the other person said and leads to a decision or suggestion; the other options just state facts."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你饿了？那我们去吃饭吧。","你不舒服？我们那回家吧。","下雨了？那我们别出去了。","他不来？那我们先走吧。"],answer:1,explain:"“那”要放在后一句的最前面，应说“你不舒服？那我们回家吧”。",explainEn:"那 must open the reply: 你不舒服？那我们回家吧."},{q:"翻译：Then we will not go.",a:"那我们不去了。",instr:"翻译",instrEn:"Translate",body:"Then we will not go."}],note:"这里“那”不是指示代词“that”，而是承接前文结果。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"nà + Sentence = in that case, …",noteEn:'Here 那 is not the demonstrative "that"; it links to the previous statement.',typeEn:"Conjunction"}]},{num:2,title:"他什么时候回来？",points:[{id:"3.2.1",name:"“……了，就……”表示两个动作连续发生",pinyin:"... le, jiù ...",type:"复句",explainEn:"Use …了，就… when one action happens and the next action follows soon after.",structure:"动作1 + 了，就 + 动作2",examples:[{zh:"我吃了饭就去学校。",en:"I will go to school after I eat.",py:"Wǒ chī le fàn jiù qù xuéxiào."},{zh:"他下了班就回家。",en:"He goes home after work.",py:"Tā xià le bān jiù huí jiā."},{zh:"你到了就给我打电话。",en:"Call me when you arrive.",py:"Nǐ dào le jiù gěi wǒ dǎ diànhuà."}],exercises:[{kind:"choice",q:"我下___课就去找你。",instr:"辨析",instrEn:"Pick the right one",body:"我下___课就去找你。",options:["了","过","着","的"],answer:0,explain:"“V了……就……”表示一个动作完成后马上做另一个动作；“过、着、的”没有这个意思。",explainEn:"V了…就… means right after one action finishes, the next happens; 过, 着 and 的 do not show this."},{kind:"choice",q:"你到了北京，就___",instr:"完成",instrEn:"Complete the sentence",body:"你到了北京，就___",options:["给我打个电话。","给我打着电话。","给我打过电话。","在给我打电话。"],answer:0,explain:"“到了……就……”说到了以后马上要做的事，这里是请求，用“给我打个电话”；“过、着、在”不表示马上要做的事。",explainEn:"到了…就… names what to do right after arriving; here it is a request, so 给我打个电话; 过/着/在 cannot express that next action."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他吃了早饭就去上班了。","我就吃了饭去学校。","你看了这本书就知道了。","我下了课就回家。"],answer:1,explain:"“就”要放在第二个动作前面，应说“我吃了饭就去学校”。",explainEn:"就 goes before the second action: 我吃了饭就去学校."},{q:"翻译：After class I will go to the library.",a:"我下了课就去图书馆。",instr:"翻译",instrEn:"Translate",body:"After class I will go to the library."}],note:"两个动作按时间先后排列，第二个动作紧接着发生。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"Action 1 + le, jiù + Action 2 = as soon as 1 is done, then 2",noteEn:"The two actions follow time order; the second happens right after the first.",typeEn:"Complex sentence"},{id:"3.2.2",name:"简单趋向补语“V + 来 / 去”",pinyin:"jiǎndān qūxiàng bǔyǔ",type:"趋向补语",explainEn:"Use 来 for movement toward the speaker, and 去 for movement away from the speaker.",structure:"动词 + 来 / 去",examples:[{zh:"请进来。",en:"Please come in.",py:"Qǐng jìnlai."},{zh:"他走出去了。",en:"He walked out.",py:"Tā zǒu chūqu le."},{zh:"你把书拿来。",en:"Bring the book here.",py:"Nǐ bǎ shū nálai."}],exercises:[{kind:"choice",q:"我在楼上，你上___吧，门开着。",instr:"辨析",instrEn:"Pick the right one",body:"我在楼上，你上___吧，门开着。",options:["去","过","来","回"],answer:2,explain:"说话人在楼上，对方向说话人这边走，用“来”；“上去”是离开说话人。",explainEn:"The speaker is upstairs and the listener comes toward him, so 来; 上去 would mean going away from the speaker."},{kind:"choice",q:"___，你快进来吧。",instr:"完成",instrEn:"Complete the sentence",body:"___，你快进来吧。",options:["我在门外面","我在学校外面","我在外面等你","我在房间里"],answer:3,explain:"“进来”表示向说话人的方向进，所以说话人应该在里面。",explainEn:"进来 means coming in toward the speaker, so the speaker must be inside."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我在教室里，你进去吧。","请你过来一下。","他回家去了。","你快下来吧，我在楼下等你。"],answer:0,explain:"说话人在教室里，对方向说话人走，应该说“你进来吧”。",explainEn:"The speaker is inside, so the listener should 进来, not 进去."},{q:"翻译：Please come up. I am upstairs.",a:"请上来，我在楼上。",instr:"翻译",instrEn:"Translate",body:"Please come up. I am upstairs."}],note:"地点宾语常放在“来/去”前：回学校去；事物宾语位置较灵活。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"Verb + lái / qù = movement toward / away from the speaker",noteEn:"A place object goes before 来/去 (回学校去); a thing object is more flexible.",typeEn:"Directional compl."},{id:"3.2.3",name:"反问句“能……吗？”",pinyin:"néng ... ma",type:"反问句",explainEn:"Use 能…吗？ as a rhetorical question. It often means the opposite of the words inside.",structure:"能 + 肯定/否定 + 吗？",examples:[{zh:"这么晚了，你能不累吗？",en:"It is so late—how could you not be tired?",py:"Zhème wǎn le, nǐ néng bú lèi ma?"},{zh:"他每天都学习，能不进步吗？",en:"He studies every day—how could he not improve?",py:"Tā měi tiān dōu xuéxí, néng bú jìnbù ma?"},{zh:"这件事我能不知道吗？",en:"How could I not know this?",py:"Zhè jiàn shì wǒ néng bù zhīdào ma?"}],exercises:[{kind:"choice",q:"他在中国住了十年，能___说汉语吗？",instr:"辨析",instrEn:"Pick the right one",body:"他在中国住了十年，能___说汉语吗？",options:["会","没","没有","不会"],answer:3,explain:"反问句“能不会……吗？”意思是“当然会”；“能会、能没、能没有”都不能这样用。",explainEn:'The rhetorical 能不会…吗？ means "of course he can"; 能会, 能没 and 能没有 cannot be used like this.'},{kind:"choice",q:"___，他能不高兴吗？",instr:"完成",instrEn:"Complete the sentence",body:"___，他能不高兴吗？",options:["他考得不好","他的手机丢了","他找不到工作","他考了一百分"],answer:3,explain:"“能不高兴吗”意思是“当然很高兴”，所以原因应该是好事。",explainEn:"能不高兴吗 means “of course he is happy”, so the reason must be good news."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他是你哥哥，你能不认识他吗？","这么好吃的菜，我能不吃吗？","这么简单的字，我能不认识呢？","他天天迟到，老师能高兴吗？"],answer:2,explain:"“能不……”反问句末要用“吗”，应说“我能不认识吗？”，或者说“我怎么能不认识呢？”。",explainEn:"The rhetorical 能不… ends with 吗: 我能不认识吗? (or 我怎么能不认识呢?)."},{q:"翻译：How could I not be happy?",a:"我能不高兴吗？",instr:"翻译",instrEn:"Translate",body:"How could I not be happy?"}],note:"反问不是在真正提问，而是强调说话人的判断。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"néng + affirmative/negative + ma? = Can …? / Is … allowed?",noteEn:"A rhetorical question isn't a real question; it stresses the speaker's judgement.",typeEn:"Rhetorical question"}]},{num:3,title:"桌子上放着很多饮料",points:[{id:"3.3.1",name:"“还是”和“或者”的区别",pinyin:"háishi / huòzhě",type:"连词",explainEn:"Use 还是 in a question with choices. Use 或者 in a statement.",structure:"问句：A 还是 B？；陈述句：A 或者 B",examples:[{zh:"你喝茶还是咖啡？",en:"Do you drink tea or coffee?",py:"Nǐ hē chá háishi kāfēi?"},{zh:"我们坐地铁或者坐公共汽车都可以。",en:"We can take the subway or the bus.",py:"Wǒmen zuò dìtiě huòzhě zuò gōnggòng qìchē dōu kěyǐ."},{zh:"你今天去还是明天去？",en:"Are you going today or tomorrow?",py:"Nǐ jīntiān qù háishi míngtiān qù?"}],exercises:[{kind:"choice",q:"你想今天去___明天去？",instr:"辨析",instrEn:"Pick the right one",body:"你想今天去___明天去？",options:["或者","还是","和","而且"],answer:1,explain:"在问句里让对方选择，用“还是”；“或者”用在陈述句里。",explainEn:"In a question offering a choice, use 还是; 或者 is for statements."},{kind:"choice",q:"A：你喝茶还是喝咖啡？B：___",instr:"完成",instrEn:"Complete the sentence",body:"A：你喝茶还是喝咖啡？B：___",options:["对，我喝茶。","喝茶吧。","是，我喝咖啡。","好的，我喝。"],answer:1,explain:"“还是”问句要直接选一个回答，不能用“对、是、好的”回答。",explainEn:"A 还是 question is answered by choosing one; 对/是/好的 answer yes-no questions."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你去还是我去？","我想喝牛奶还是咖啡。","星期六或者星期天都行。","你要大的还是小的？"],answer:1,explain:"这是陈述句，不是问句，应该用“或者”：“我想喝牛奶或者咖啡”。",explainEn:"This is a statement, not a question, so use 或者: 我想喝牛奶或者咖啡."},{q:"翻译：Do you want tea or coffee?",a:"你要茶还是咖啡？",instr:"翻译",instrEn:"Translate",body:"Do you want tea or coffee?"}],note:"最简单记法：有选择的疑问句用“还是”；陈述句常用“或者”。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:'Question: A háishi B? ; Statement: A huòzhě B = "or" in questions vs statements',noteEn:"Simple rule: use 还是 in choice questions, 或者 in statements.",typeEn:"Conjunction"},{id:"3.3.2",name:"存在句：“地点 + V着 + 名词”",pinyin:"dìdiǎn + V-zhe + míngcí",type:"存在句",explainEn:"Use place + V着 + noun to say something exists in a place and stays in a state.",structure:"地点 + 动词 + 着 + 名词",examples:[{zh:"桌子上放着一本书。",en:"There is a book on the table.",py:"Zhuōzi shang fàng zhe yì běn shū."},{zh:"墙上挂着一张照片。",en:"There is a photo hanging on the wall.",py:"Qiáng shang guà zhe yì zhāng zhàopiàn."},{zh:"门口站着一个人。",en:"There is a person standing at the door.",py:"Ménkǒu zhàn zhe yí ge rén."}],exercises:[{kind:"choice",q:"黑板上___几个汉字。",instr:"辨析",instrEn:"Pick the right one",body:"黑板上___几个汉字。",options:["在写","写在","正写","写着"],answer:3,explain:"说某个地方存在什么东西，用“地点 + V着 + 名词”；“写在”后面要接地点。",explainEn:"To say something exists in a place, use place + V着 + noun; 写在 must be followed by a place."},{kind:"choice",q:"___放着很多书。",instr:"完成",instrEn:"Complete the sentence",body:"___放着很多书。",options:["桌子上","桌子","书包","我的书包"],answer:0,explain:"存在句开头要用地点词，“桌子”要加“上”，“书包”要加“里”才是地点。",explainEn:"An existential sentence starts with a place word; 桌子 needs 上 and 书包 needs 里."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["门口站着两个学生。","墙上挂着一张地图。","一本词典放着桌子上。","桌子上放着一杯咖啡。"],answer:2,explain:"存在句要把地点放前面、东西放后面，应说“桌子上放着一本词典”。",explainEn:"The place comes first and the thing last: 桌子上放着一本词典."},{q:"翻译：There are a lot of people sitting in the room.",a:"房间里坐着很多人。",instr:"翻译",instrEn:"Translate",body:"There are a lot of people sitting in the room."}],note:"重点是“存在 + 持续状态”，不是强调动作正在进行。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"Place + Verb + zhe + Noun = sth is in a state of … at a place",noteEn:"The point is existence + a lasting state, not an action in progress.",typeEn:"Existential sentence"},{id:"3.3.3",name:"“会”表示可能",pinyin:"huì",type:"能愿动词",explainEn:"Use 会 to say something is likely or possible to happen.",structure:"会 + 动词 / 形容词",examples:[{zh:"明天会下雨。",en:"It may rain tomorrow.",py:"Míngtiān huì xià yǔ."},{zh:"他会来的。",en:"He will probably come.",py:"Tā huì lái de."},{zh:"晚上会冷一点儿。",en:"It may be a little cold at night.",py:"Wǎnshang huì lěng yìdiǎnr."}],exercises:[{kind:"choice",q:"天这么黑，一会儿___下雨的。",instr:"辨析",instrEn:"Pick the right one",body:"天这么黑，一会儿___下雨的。",options:["能","会","可以","想"],answer:1,explain:"“会……的”表示估计有可能发生；“能、可以”表示能力或允许，“想”表示愿望，都不对。",explainEn:"会…的 shows a likely future event; 能 and 可以 mean ability or permission, 想 means want."},{kind:"choice",q:"放心吧，你这么努力，考试一定会___",instr:"完成",instrEn:"Complete the sentence",body:"放心吧，你这么努力，考试一定会___",options:["考得很好了。","考得很好的。","考了很好。","考很好了。"],answer:1,explain:"“会……的”表示估计将来会这样，“一定会考得很好的”；“会”说的是还没发生的事，后面不能用“了”。",explainEn:"会…的 predicts a future result: 一定会考得很好的; since 会 is about the future, 了 does not fit."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我昨天会去你家。","明天会很热。","别着急，他会来的。","这么晚了，商店会关门吗？"],answer:0,explain:"表示可能的“会”说的是还没发生的事，“昨天”已经过去了，应说“我昨天去了你家”。",explainEn:"会 for possibility is about the future; 昨天 is past, so say 我昨天去了你家."},{q:"翻译：Do not worry, he will call you.",a:"别担心，他会给你打电话的。",instr:"翻译",instrEn:"Translate",body:"Do not worry, he will call you."}],note:"这里“会”表示可能，不是“会说汉语”的技能意义。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"huì + Verb / Adjective = will / is likely to",noteEn:'Here 会 means likelihood, not the "know how to" sense (as in 会说汉语).',typeEn:"Modal verb"}]},{num:4,title:"她总是笑着跟客人说话",points:[{id:"3.4.1",name:"“又……又……”表示两个特点同时存在",pinyin:"yòu ... yòu ...",type:"并列结构",explainEn:"Use 又…又… to say someone or something has two qualities at the same time.",structure:"又 + 形容词/动词 + 又 + 形容词/动词",examples:[{zh:"这个苹果又大又甜。",en:"This apple is big and sweet.",py:"Zhège píngguǒ yòu dà yòu tián."},{zh:"她又漂亮又热情。",en:"She is pretty and warm-hearted.",py:"Tā yòu piàoliang yòu rèqíng."},{zh:"这个地方又安静又干净。",en:"This place is quiet and clean.",py:"Zhège dìfang yòu ānjìng yòu gānjìng."}],exercises:[{kind:"choice",q:"这家饭馆的菜___好吃又便宜。",instr:"辨析",instrEn:"Pick the right one",body:"这家饭馆的菜___好吃又便宜。",options:["和","一边","又","越"],answer:2,explain:"后面有“又便宜”，前面也要用“又”，说两个特点同时存在；“一边”用于两个动作，“和”不能连接两个形容词谓语，“越”要和“越”配对。",explainEn:"With 又便宜 after it, the first slot also needs 又 for two qualities at once; 一边 is for two actions, 和 cannot join two adjective predicates, and 越 pairs with 越."},{kind:"choice",q:"这件衣服又贵又___，我不买。",instr:"完成",instrEn:"Complete the sentence",body:"这件衣服又贵又___，我不买。",options:["漂亮","舒服","便宜","难看"],answer:3,explain:"“又……又……”连接的两个特点意思方向要一样，“贵”是不好的，后面也要是不好的特点。",explainEn:"The two qualities in 又…又… must go the same way; 贵 is negative, so the second must be negative too."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他的房间又大和干净。","他又高又瘦。","这里的东西又多又便宜。","她的房间又干净又漂亮。"],answer:0,explain:"“又……又……”两个“又”都要有，不能用“和”，应说“他的房间又大又干净”。",explainEn:"Both 又 are required and 和 cannot replace the second one: 他的房间又大又干净."},{q:"翻译：This bag is cheap and good-looking.",a:"这个包又便宜又好看。",instr:"翻译",instrEn:"Translate",body:"This bag is cheap and good-looking."}],note:"两个部分一般是相同词性的特点或动作。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"yòu + Adj/Verb + yòu + Adj/Verb = both … and …",noteEn:"The two parts are usually features/actions of the same word class.",typeEn:"Coordinate structure"},{id:"3.4.2",name:"伴随动作：“V1着（O1）+ V2（O2）”",pinyin:"V1-zhe + V2",type:"伴随结构",explainEn:"Use V1着 + V2 when one action is the manner/background of another action.",structure:"V1 + 着 (+ O1) + V2 (+ O2)",examples:[{zh:"她笑着说话。",en:"She speaks with a smile.",py:"Tā xiào zhe shuōhuà."},{zh:"他坐着看电视。",en:"He watches TV while sitting.",py:"Tā zuò zhe kàn diànshì."},{zh:"老师拿着书进来了。",en:"The teacher came in holding a book.",py:"Lǎoshī ná zhe shū jìnlai le."}],exercises:[{kind:"choice",q:"老师站___给我们上课。",instr:"辨析",instrEn:"Pick the right one",body:"老师站___给我们上课。",options:["了","着","过","在"],answer:1,explain:"“站着”表示上课时的状态，用“V1着 + V2”；“了、过”不表示伴随，“站在”后面要接地点。",explainEn:"站着 shows the state during the main action (V1着 + V2); 站在 needs a place after it."},{kind:"choice",q:"他笑着说“没关系”，___",instr:"完成",instrEn:"Complete the sentence",body:"他笑着说“没关系”，___",options:["说完以后才笑了。","看起来一点儿也不生气。","笑完以后才说话。","先说话，然后又笑了。"],answer:1,explain:"“笑着说”表示说话的时候在笑，两个动作同时进行，所以他不生气；“说完才笑、笑完才说、先说再笑”都是先后发生。",explainEn:"笑着说 means smiling while speaking, at the same time, so he is not angry; the other options describe one action after the other."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他看电视着吃饭。","他听着音乐跑步。","妈妈笑着说：“快来吃饭。”","我们走着去学校吧。"],answer:0,explain:"“着”要紧跟在第一个动词后面，应说“他看着电视吃饭”。",explainEn:"着 must come right after the first verb: 他看着电视吃饭."},{q:"翻译：The children came in singing.",a:"孩子们唱着歌走进来了。",instr:"翻译",instrEn:"Translate",body:"The children came in singing."}],note:"V1是伴随状态，V2是主要动作。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"V1 + zhe (+ O1) + V2 (+ O2) = do V2 while V1-ing",noteEn:"V1 is the accompanying manner/state; V2 is the main action.",typeEn:"Accompanying structure"}]},{num:5,title:"我最近越来越胖了",points:[{id:"3.5.1",name:"句末“了”表示情况发生变化",pinyin:"le",type:"助词",explainEn:"Use sentence-final 了 to show a new situation or a change.",structure:"句子 + 了",examples:[{zh:"天气冷了。",en:"The weather has become cold.",py:"Tiānqì lěng le."},{zh:"我不喝咖啡了。",en:"I do not drink coffee anymore.",py:"Wǒ bù hē kāfēi le."},{zh:"他现在是老师了。",en:"He is a teacher now.",py:"Tā xiànzài shì lǎoshī le."}],exercises:[{kind:"choice",q:"我以前天天吃肉，现在不吃___。",instr:"辨析",instrEn:"Pick the right one",body:"我以前天天吃肉，现在不吃___。",options:["过","着","了","吧"],answer:2,explain:"句末“了”表示情况变了：以前吃，现在不吃；“过、着”不能这样用，“吧”表示商量或猜测。",explainEn:"Sentence-final 了 marks the change from eating meat to not eating it; 过/着 cannot be used, and 吧 suggests or guesses."},{kind:"choice",q:"我不坐地铁了，___",instr:"完成",instrEn:"Complete the sentence",body:"我不坐地铁了，___",options:["以前也没坐过。","我一直不坐地铁。","今天还要坐地铁去。","现在骑自行车上班。"],answer:3,explain:"句末“了”表示变化：以前坐地铁，现在不坐了，换成骑自行车；“以前也没坐过、一直不坐”都说明没有变化。",explainEn:'Final 了 shows a change: the speaker used to take the subway and now cycles; "never took it" or "always did not" means no change.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["天黑了，我们回家吧。","他病好了，可以上学了。","他以前是医生了。","我现在会游泳了。"],answer:2,explain:"句末“了”表示现在的新情况，说“以前”的情况不用，应说“他以前是医生”。",explainEn:"Final 了 marks a new situation now; for a past fact just say 他以前是医生."},{q:"翻译：My little brother has grown taller.",a:"弟弟长高了。",instr:"翻译",instrEn:"Translate",body:"My little brother has grown taller."}],note:"重点是“现在和以前不一样了”。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"Sentence + le = a new or changed situation",noteEn:'The point is "things are different from before now".',typeEn:"Particle"},{id:"3.5.2",name:"“越来越……”表示变化不断发展",pinyin:"yuèláiyuè",type:"程度结构",explainEn:"Use 越来越 + adjective/mental verb to mean “more and more…”.",structure:"越来越 + 形容词 / 心理动词",examples:[{zh:"天气越来越冷了。",en:"The weather is getting colder and colder.",py:"Tiānqì yuè lái yuè lěng le."},{zh:"他的汉语越来越好了。",en:"His Chinese is getting better and better.",py:"Tā de Hànyǔ yuè lái yuè hǎo le."},{zh:"我越来越喜欢这个城市了。",en:"I like this city more and more.",py:"Wǒ yuè lái yuè xǐhuan zhège chéngshì le."}],exercises:[{kind:"choice",q:"天气越来越___了。",instr:"辨析",instrEn:"Pick the right one",body:"天气越来越___了。",options:["很热","非常热","热一点儿","热"],answer:3,explain:"“越来越”后面直接加形容词，不能再加“很、非常”，也不能加“一点儿”。",explainEn:"越来越 takes a bare adjective; no 很 or 非常 before it and no 一点儿 after it."},{kind:"choice",q:"他的汉语越来越好了，___",instr:"完成",instrEn:"Complete the sentence",body:"他的汉语越来越好了，___",options:["现在能跟中国人聊天了。","可是一直跟以前一样。","还是一句也不会说。","一点儿变化也没有。"],answer:0,explain:"“越来越好”表示一直在进步、不断变化，所以现在能聊天了；“跟以前一样、没有变化”和它的意思相反。",explainEn:'越来越好 means steadily improving, so he can now chat; "the same as before" or "no change" contradicts it.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他越来越高了。","我越来越喜欢这儿了。","这儿的东西越来越很贵了。","天越来越黑了。"],answer:2,explain:"“越来越”后面不能加“很”，应说“越来越贵了”。",explainEn:"No 很 after 越来越: 越来越贵了."},{q:"翻译：There are more and more cars.",a:"车越来越多了。",instr:"翻译",instrEn:"Translate",body:"There are more and more cars."}],note:"“越来越”后面通常直接接形容词或少数心理动词。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"yuè lái yuè + Adjective / mental verb = more and more …",noteEn:"越来越 is usually followed directly by an adjective or a few mental verbs.",typeEn:"Degree structure"}]},{num:6,title:"怎么突然找不到了",points:[{id:"3.6.1",name:"可能补语：“V得 / V不 + 补语”",pinyin:"kěnéng bǔyǔ",type:"可能补语",explainEn:"Use V得/不 + complement to say an action can or cannot reach a result.",structure:"动词 + 得/不 + 结果/趋向补语",examples:[{zh:"这个字我看得懂。",en:"I can understand this character.",py:"Zhège zì wǒ kàn de dǒng."},{zh:"太远了，我走不到。",en:"It is too far; I cannot get there on foot.",py:"Tài yuǎn le, wǒ zǒu bu dào."},{zh:"声音太小，我听不见。",en:"The sound is too low; I cannot hear it.",py:"Shēngyīn tài xiǎo, wǒ tīng bu jiàn."}],exercises:[{kind:"choice",q:"黑板上的字太小了，我看___。",instr:"辨析",instrEn:"Pick the right one",body:"黑板上的字太小了，我看___。",options:["不清楚","没清楚","不能清楚","清楚不了"],answer:0,explain:"说没有能力达到结果，用“V不 + 补语”，就是“看不清楚”；不能说“没清楚、不能清楚”，“不了”也不能放在“清楚”后面。",explainEn:"To say you cannot reach the result, use V不 + complement: 看不清楚. 没清楚, 不能清楚 and 看清楚不了 are wrong."},{kind:"choice",q:"这个箱子我一个人搬得动，___",instr:"完成",instrEn:"Complete the sentence",body:"这个箱子我一个人搬得动，___",options:["你快来帮帮我。","我们两个人一起搬吧。","你去找个人来帮我吧。","你不用帮我了。"],answer:3,explain:"“搬得动”表示有能力搬，所以不用别人帮忙；其他几句都是“搬不动”时才说的话。",explainEn:"搬得动 means able to move it, so no help is needed; the other options fit 搬不动."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这个问题我回答不了。","我不能听懂他的话。","太晚了，我们回不去了。","他说得太快，我听不懂。"],answer:1,explain:"表示没有能力达到“懂”的结果，要用可能补语：“我听不懂他的话”。",explainEn:"To say you cannot understand, use the potential form: 我听不懂他的话."},{q:"翻译：I cannot hear it.",a:"我听不见。",instr:"翻译",instrEn:"Translate",body:"I cannot hear it."}],note:"可能补语说“能不能达到结果”，和一般的“能 + 动词”意思接近但结构不同。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"Verb + de/bù + resultative/directional complement = can / cannot + result",noteEn:"A potential complement says whether a result can be reached; close to 能 + verb but different in structure.",typeEn:"Potential compl."},{id:"3.6.2",name:"“名词 + 呢？”询问人或东西在哪里",pinyin:"míngcí + ne",type:"疑问句",explainEn:"Use noun + 呢？ when the context means “Where is …?”.",structure:"名词 / 代词 + 呢？",examples:[{zh:"我的手机呢？",en:"Where is my phone?",py:"Wǒ de shǒujī ne?"},{zh:"李老师呢？",en:"Where is Teacher Li?",py:"Lǐ lǎoshī ne?"},{zh:"你的书呢？",en:"Where is your book?",py:"Nǐ de shū ne?"}],exercises:[{kind:"choice",q:"我的手机___？我找了很久都没找到。",instr:"辨析",instrEn:"Pick the right one",body:"我的手机___？我找了很久都没找到。",options:["吗","吧","啊","呢"],answer:3,explain:"“名词 + 呢？”可以问东西在哪儿；“吗、吧、啊”放在名词后面没有问地方的意思。",explainEn:'Noun + 呢？ can ask where something is; 吗, 吧 and 啊 after a noun cannot ask "where".'},{kind:"choice",q:"A：妈妈呢？B：___",instr:"完成",instrEn:"Complete the sentence",body:"A：妈妈呢？B：___",options:["她很好。","她四十岁。","她在厨房。","她是老师。"],answer:2,explain:"没有上下文时，“妈妈呢？”是问妈妈在哪儿，所以要回答地方。",explainEn:"With no other context, 妈妈呢？ asks where Mom is, so the answer is a place."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我的护照呢？","你的书在这儿，他的书呢？","你的自行车呢在哪儿？","小王呢？他还没来吗？"],answer:2,explain:"“自行车呢？”已经是问在哪儿，不能再加“在哪儿”，说“你的自行车呢？”或“你的自行车在哪儿？”。",explainEn:"自行车呢？ already asks where; drop 在哪儿 or drop 呢."},{q:"翻译：Where is your older brother?",a:"你哥哥呢？",instr:"翻译",instrEn:"Translate",body:"Where is your older brother?"}],note:"这里“呢”省略了“在哪儿”。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"Noun / Pronoun + ne? = What about …?",noteEn:'Here 呢 leaves out "在哪儿 (where)".',typeEn:"Question"},{id:"3.6.3",name:"“刚”和“刚才”的区别",pinyin:"gāng / gāngcái",type:"时间表达",explainEn:"刚 means “just” and goes before a verb. 刚才 means “just now” and is a time word.",structure:"刚 + 动词；刚才 + 句子",examples:[{zh:"我刚到家。",en:"I just got home.",py:"Wǒ gāng dào jiā."},{zh:"刚才他给我打电话了。",en:"He called me just now.",py:"Gāngcái tā gěi wǒ dǎ diànhuà le."},{zh:"我刚吃完饭。",en:"I just finished eating.",py:"Wǒ gāng chī wán fàn."}],exercises:[{kind:"choice",q:"他___来两天，还不认识路。",instr:"辨析",instrEn:"Pick the right one",body:"他___来两天，还不认识路。",options:["刚","刚才","马上","以前"],answer:0,explain:"“刚”放在动词前，后面可以有时段，表示时间不长；“刚才”是时间词，指说话前不久，不能接“两天”。",explainEn:'刚 goes before the verb and can take a duration ("only two days"); 刚才 is a time word meaning "a moment ago" and cannot take 两天.'},{kind:"choice",q:"他刚才还在这儿，___",instr:"完成",instrEn:"Complete the sentence",body:"他刚才还在这儿，___",options:["现在不知道去哪儿了。","他很久没来过了。","已经走了一年了。","明天才会来这儿。"],answer:0,explain:"“刚才”指说话前不久，所以他刚走不久，不知道去哪儿了；“一年、很久、明天”都和“刚才”的时间不合。",explainEn:'刚才 means a moment ago, so he only just left; "a year", "a long time" or "tomorrow" do not fit.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我刚下课。","我刚才来北京两个星期。","刚才谁给你打电话了？","他刚走，你快去找他吧。"],answer:1,explain:"后面有时段“两个星期”，要用“刚”，应说“我刚来北京两个星期”。",explainEn:"With a duration like 两个星期, use 刚: 我刚来北京两个星期."},{q:"翻译：He has just gone out.",a:"他刚出去。",instr:"翻译",instrEn:"Translate",body:"He has just gone out."}],note:"“刚”是副词；“刚才”是时间名词，可以放在主语前。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"gāng + Verb; gāngcái + Sentence = just (a moment ago)",noteEn:"刚 is an adverb; 刚才 is a time noun and can go before the subject.",typeEn:"Time"}]},{num:7,title:"我跟她都认识五年了",points:[{id:"3.7.1",name:"时段的表达：动作持续多长时间",pinyin:"shíduàn de biǎodá",type:"时间表达",explainEn:"Put a duration after the verb to say how long an action or state lasts.",structure:"主语 + 动词 +（了）+ 时段 +（了）",examples:[{zh:"我学汉语三年了。",en:"I have studied Chinese for three years.",py:"Wǒ xué Hànyǔ sān nián le."},{zh:"他在北京住了两年。",en:"He lived in Beijing for two years.",py:"Tā zài Běijīng zhù le liǎng nián."},{zh:"我等了你十分钟。",en:"I waited for you for ten minutes.",py:"Wǒ děng le nǐ shí fēnzhōng."}],exercises:[{kind:"choice",q:"昨天晚上我___。",instr:"辨析",instrEn:"Pick the right one",body:"昨天晚上我___。",options:["看了两个小时书","看书了两个小时","两个小时看了书","看了书两个小时"],answer:0,explain:"动词带宾语时，时段放在动词和宾语中间：“看了两个小时书”。",explainEn:"With a verb + object, the duration goes between them: 看了两个小时书."},{kind:"choice",q:"我学汉语学了一年了，___",instr:"完成",instrEn:"Complete the sentence",body:"我学汉语学了一年了，___",options:["去年就不学了。","还想再学两年。","后来就不学了。","已经不学很久了。"],answer:1,explain:"句末有“了”的“学了一年了”表示到现在还在学，所以后面说还要继续学。",explainEn:"学了一年了 (with final 了) means still studying now, so he plans to continue."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我每天睡觉八个小时。","他在北京住了三年。","我等了他一个小时。","我们已经认识十年了。"],answer:0,explain:"“睡觉”是动词加宾语，时段要放中间，应说“我每天睡八个小时觉”。",explainEn:"睡觉 is verb + object; put the duration inside: 我每天睡八个小时觉."},{q:"翻译：She has lived here for five years.",a:"她在这儿住了五年了。",instr:"翻译",instrEn:"Translate",body:"She has lived here for five years."}],note:"“时段”表示长度，如十分钟、两个月、三年。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"Subject + Verb + (le) + duration + (le) = has been doing sth for …",noteEn:"A duration shows length, e.g. ten minutes, two months, three years.",typeEn:"Time"},{id:"3.7.2",name:"“对……感兴趣”表示兴趣",pinyin:"duì ... gǎn xìngqù",type:"介词结构",explainEn:"Use 对…感兴趣 to say “be interested in…”.",structure:"对 + 人/事物 + 感兴趣",examples:[{zh:"我对中国文化很感兴趣。",en:"I am very interested in Chinese culture.",py:"Wǒ duì Zhōngguó wénhuà hěn gǎn xìngqù."},{zh:"他对音乐感兴趣。",en:"He is interested in music.",py:"Tā duì yīnyuè gǎn xìngqù."},{zh:"你对什么感兴趣？",en:"What are you interested in?",py:"Nǐ duì shénme gǎn xìngqù?"}],exercises:[{kind:"choice",q:"我___中国画很感兴趣。",instr:"辨析",instrEn:"Pick the right one",body:"我___中国画很感兴趣。",options:["给","跟","对","向"],answer:2,explain:"固定说法是“对……感兴趣”，不能用“给、跟、向”。",explainEn:"The fixed pattern is 对…感兴趣; 给, 跟 and 向 are not used."},{kind:"choice",q:"A：你对什么感兴趣？B：___",instr:"完成",instrEn:"Complete the sentence",body:"A：你对什么感兴趣？B：___",options:["画画儿对我很感兴趣。","我对画画儿很感兴趣。","我感兴趣对画画儿。","我对画画儿很有意思。"],answer:1,explain:"“对”后面是让人有兴趣的事物，前面是有兴趣的人：“我对画画儿很感兴趣”；“对……”要放在“感兴趣”前面，“有意思”说的是事物本身，不能说“我对……很有意思”。",explainEn:"The person who is interested comes first and the thing goes after 对: 我对画画儿很感兴趣. 对… must come before 感兴趣, and 有意思 describes the thing itself, so 我对…很有意思 is wrong."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他对音乐很感兴趣。","我很感兴趣中国文化。","你对什么运动感兴趣？","我对中国菜特别感兴趣。"],answer:1,explain:"“感兴趣”后面不能直接带宾语，要用“对”把事物放前面：“我对中国文化很感兴趣”。",explainEn:"感兴趣 takes no object; use 对 before it: 我对中国文化很感兴趣."},{q:"翻译：My younger sister is interested in drawing.",a:"我妹妹对画画儿很感兴趣。",instr:"翻译",instrEn:"Translate",body:"My younger sister is interested in drawing."}],note:"“感兴趣”前常用介词“对”引出对象。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"duì + person/thing + gǎn xìngqù = be interested in …",noteEn:"Use 对 before 感兴趣 to introduce what you're interested in.",typeEn:"Prep. phrase"},{id:"3.7.3",name:"用“半、刻、差”表示时间",pinyin:"bàn / kè / chà",type:"时间表达",explainEn:"Use 半 for half past, 刻 for a quarter, and 差 for minutes before the next hour.",structure:"X点半；X点一刻；差X分/一刻Y点",examples:[{zh:"现在三点半。",en:"It is 3:30 now.",py:"Xiànzài sān diǎn bàn."},{zh:"我们四点一刻见。",en:"We will meet at 4:15.",py:"Wǒmen sì diǎn yí kè jiàn."},{zh:"现在差一刻五点。",en:"It is a quarter to five.",py:"Xiànzài chà yí kè wǔ diǎn."}],exercises:[{kind:"choice",q:"现在是七点四十五，也就是___八点。",instr:"辨析",instrEn:"Pick the right one",body:"现在是七点四十五，也就是___八点。",options:["差一刻","差三刻","一刻","半"],answer:0,explain:"七点四十五离八点还有十五分钟，十五分钟是“一刻”，所以是“差一刻八点”。",explainEn:"7:45 is 15 minutes (一刻) before 8, so 差一刻八点."},{kind:"choice",q:"电影七点半开始，现在差五分七点，___",instr:"完成",instrEn:"Complete the sentence",body:"电影七点半开始，现在差五分七点，___",options:["还有三十五分钟。","还有五分钟。","已经开始了。","还有半个小时。"],answer:0,explain:"“差五分七点”是六点五十五，到七点半还有三十五分钟。",explainEn:"差五分七点 is 6:55, so there are 35 minutes until 7:30."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我们三点半见。","现在差十分九点。","我每天六点一刻起床。","现在是四点两刻。"],answer:3,explain:"三十分钟说“半”，不说“两刻”，应说“现在是四点半”。",explainEn:"Thirty minutes is 半, not 两刻: 现在是四点半."},{q:"翻译：a quarter past four",a:"四点一刻",instr:"翻译",instrEn:"Translate",body:"a quarter past four"}],note:"“刻”=15分钟；“差”从下一个整点往前算。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"X diǎn bàn; X diǎn yí kè; chà X fēn / yí kè Y diǎn = half past / quarter past / to",noteEn:"刻 = 15 minutes; 差 counts back from the next full hour.",typeEn:"Time"}]},{num:8,title:"你去哪儿我就去哪儿",points:[{id:"3.8.1",name:"“又”和“再”表示重复",pinyin:"yòu / zài",type:"副词",explainEn:"Use 又 for a repeated action that already happened. Use 再 for a repeated action in the future.",structure:"已经发生：又 + V；未发生：再 + V",examples:[{zh:"他昨天迟到，今天又迟到了。",en:"He was late yesterday and is late again today.",py:"Tā zuótiān chídào, jīntiān yòu chídào le."},{zh:"这本书很好，我想再看一次。",en:"This book is good; I want to read it again.",py:"Zhè běn shū hěn hǎo, wǒ xiǎng zài kàn yí cì."},{zh:"我昨天去了，明天还要再去。",en:"I went yesterday and will go again tomorrow.",py:"Wǒ zuótiān qù le, míngtiān hái yào zài qù."}],exercises:[{kind:"choice",q:"这个菜很好吃，下次我们___来吃吧。",instr:"辨析",instrEn:"Pick the right one",body:"这个菜很好吃，下次我们___来吃吧。",options:["又","才","再","刚"],answer:2,explain:"“下次”是还没发生的事，重复要用“再”；“又”用在已经发生的重复，“才、刚”也不能说下次的事。",explainEn:"下次 is about the future, so repetition takes 再; 又 is for repetition that already happened, and 才/刚 cannot talk about next time."},{kind:"choice",q:"你说得太快了，请再___。",instr:"完成",instrEn:"Complete the sentence",body:"你说得太快了，请再___。",options:["说了一次","说一次","说过一次","说着一次"],answer:1,explain:"“再”说的是还没做的事，后面的动词不能带“了、过、着”。",explainEn:"再 is about something not done yet, so the verb takes no 了, 过 or 着."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他昨天来了，今天又来了。","我昨天再给他打了电话。","这个电影真好看，我想再看一次。","你明天再来吧。"],answer:1,explain:"“昨天”已经发生，重复要用“又”，应说“我昨天又给他打了电话”。",explainEn:"昨天 is past, so use 又: 我昨天又给他打了电话."}],note:"简单记：过去/已发生多用“又”；未来/还没发生多用“再”。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:'Already happened: yòu + V; not yet: zài + V = "again" past vs future',noteEn:"Simple rule: 又 for the past/done, 再 for the future/not yet.",typeEn:"Adverb"},{id:"3.8.2",name:"疑问代词活用1：“疑问代词 + 就 + 疑问代词”",pinyin:"yíwèn dàicí huóyòng 1",type:"代词结构",explainEn:"Repeat the same question word around 就 to mean “whatever / wherever / whenever…”.",structure:"疑问代词 + … + 就 + 疑问代词 + …",examples:[{zh:"你去哪儿，我就去哪儿。",en:"I will go wherever you go.",py:"Nǐ qù nǎr, wǒ jiù qù nǎr."},{zh:"你吃什么，我就吃什么。",en:"I will eat whatever you eat.",py:"Nǐ chī shénme, wǒ jiù chī shénme."},{zh:"你什么时候来，我就什么时候来。",en:"I will come whenever you come.",py:"Nǐ shénme shíhou lái, wǒ jiù shénme shíhou lái."}],exercises:[{kind:"choice",q:"你想买什么，我就给你买___。",instr:"辨析",instrEn:"Pick the right one",body:"你想买什么，我就给你买___。",options:["哪儿","什么","谁","怎么"],answer:1,explain:"前后要用同一个疑问代词，前面是“什么”，后面也要用“什么”。",explainEn:"Both halves must use the same question word: 什么 … 什么."},{kind:"choice",q:"谁先到，___",instr:"完成",instrEn:"Complete the sentence",body:"谁先到，___",options:["我就买票。","他就买票。","谁就买票。","谁也买票。"],answer:2,explain:"这个格式前后用同一个疑问代词，并用“就”连接：“谁……，谁就……”。",explainEn:"The pattern repeats the same question word with 就: 谁…，谁就…."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你想去哪儿，我们就去哪儿。","你喜欢什么，我就买哪个。","你想怎么做，就怎么做。","谁想去，谁就去。"],answer:1,explain:"前后的疑问代词要一样，应说“你喜欢什么，我就买什么”。",explainEn:"The two question words must match: 你喜欢什么，我就买什么."},{q:"翻译：Sit wherever you like.",a:"你想坐哪儿，就坐哪儿。",instr:"翻译",instrEn:"Translate",body:"Sit wherever you like."}],note:"前后通常使用同一个疑问代词；此时不是真正提问。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"question word + … + jiù + same question word + … = whatever/whoever …, that one",noteEn:"The same question word appears twice; it isn't a real question.",typeEn:"Pronoun structure"}]},{num:9,title:"她的汉语说得跟中国人一样好",points:[{id:"3.9.1",name:"“越A越B”表示两个变化一起发展",pinyin:"yuè A yuè B",type:"程度结构",explainEn:"Use 越 A 越 B to mean “the more A, the more B”.",structure:"越 + A + 越 + B",examples:[{zh:"天气越冷，我越想喝热茶。",en:"The colder it gets, the more I want hot tea.",py:"Tiānqì yuè lěng, wǒ yuè xiǎng hē rè chá."},{zh:"他越说越快。",en:"The more he talks, the faster he speaks.",py:"Tā yuè shuō yuè kuài."},{zh:"汉语越学越有意思。",en:"The more I study Chinese, the more interesting it becomes.",py:"Hànyǔ yuè xué yuè yǒu yìsi."}],exercises:[{kind:"choice",q:"外面的雨越下___大。",instr:"辨析",instrEn:"Pick the right one",body:"外面的雨越下___大。",options:["越","更","越来越","很"],answer:0,explain:"“越A越B”两个“越”都要有，“越下越大”；不能换成“更、越来越、很”。",explainEn:"越A越B needs both 越: 越下越大; 更, 越来越 or 很 cannot replace the second one."},{kind:"choice",q:"我越想越___，就给他打了个电话。",instr:"完成",instrEn:"Complete the sentence",body:"我越想越___，就给他打了个电话。",options:["放心","想睡觉","不放心","不想打电话"],answer:2,explain:"“越想越……”表示想得越多感觉越强，越想越不放心，所以打电话。",explainEn:"越想越… means the feeling grows the more you think; growing worry leads to the call."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他越说越很快。","他越跑越快。","这个歌我越听越喜欢。","你越说，我越不明白。"],answer:0,explain:"“越A越B”的B前面不能加“很”，应说“他越说越快”。",explainEn:"No 很 before B in 越A越B: 他越说越快."},{q:"翻译：The more she sings, the better it sounds.",a:"她越唱越好听。",instr:"翻译",instrEn:"Translate",body:"The more she sings, the better it sounds."}],note:"两个“越”后面的内容可以是动作，也可以是状态。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"yuè + A + yuè + B = the more A, the more B",noteEn:"After each 越 you can have either an action or a state.",typeEn:"Degree structure"},{id:"3.9.2",name:"比较句1：“A 跟 B 一样（+ 形容词）”",pinyin:"A gēn B yíyàng",type:"比较句",explainEn:"Use A 跟 B 一样 (+ adjective) to say A and B are the same.",structure:"A + 跟 + B + 一样 +（形容词）",examples:[{zh:"他跟我一样高。",en:"He is as tall as I am.",py:"Tā gēn wǒ yíyàng gāo."},{zh:"这个跟那个一样贵。",en:"This one is as expensive as that one.",py:"Zhège gēn nàge yíyàng guì."},{zh:"她说汉语跟老师一样好。",en:"She speaks Chinese as well as the teacher.",py:"Tā shuō Hànyǔ gēn lǎoshī yíyàng hǎo."}],exercises:[{kind:"choice",q:"这件衣服跟那件___贵。",instr:"辨析",instrEn:"Pick the right one",body:"这件衣服跟那件___贵。",options:["一样","一起","也","比"],answer:0,explain:"比较两个东西相同用“A跟B一样 + 形容词”；“一起”说一起做事，“也、比”不能放在“跟那件”后面。",explainEn:"To say two things are the same use A跟B一样 + adjective; 一起 is for doing things together, and 也/比 cannot follow 跟那件."},{kind:"choice",q:"我跟哥哥一样高，___",instr:"完成",instrEn:"Complete the sentence",body:"我跟哥哥一样高，___",options:["他比我高一点儿。","都是一米八。","我比他矮一些。","我们一个高一个矮。"],answer:1,explain:"“一样高”表示身高相同，所以两个人都是一米八。",explainEn:"一样高 means the same height, so both are 1.8 m."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我一样跟他忙。","我的爱好跟你一样。","今天跟昨天一样热。","这个字跟那个字不一样。"],answer:0,explain:"“跟……一样”要整个放在形容词前面，“一样”不能放到“跟”前面，应说“我跟他一样忙”。",explainEn:"The whole 跟…一样 goes before the adjective; 一样 can't come before 跟. Say 我跟他一样忙."},{q:"翻译：My room is as big as yours.",a:"我的房间跟你的一样大。",instr:"翻译",instrEn:"Translate",body:"My room is as big as yours."}],note:"“一样”后可直接结束，也可再加形容词说明哪方面一样。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"A + gēn + B + yíyàng + (Adjective) = A is the same as B (in …)",noteEn:"一样 can end the clause or be followed by an adjective saying how they're alike.",typeEn:"Comparison"}]},{num:10,title:"数学比历史难多了",points:[{id:"3.10.1",name:"比较句2：“A 比 B + Adj + 一点儿/一些/得多/多了”",pinyin:"A bǐ B + adj",type:"比较句",explainEn:"Use 比 to compare. Add 一点儿/一些 for a small difference, and 得多/多了 for a big difference.",structure:"A + 比 + B + 形容词 + 一点儿/一些/得多/多了",examples:[{zh:"今天比昨天冷一点儿。",en:"Today is a little colder than yesterday.",py:"Jīntiān bǐ zuótiān lěng yìdiǎnr."},{zh:"数学比历史难多了。",en:"Math is much harder than history.",py:"Shùxué bǐ lìshǐ nán duō le."},{zh:"这件衣服比那件贵一些。",en:"This clothing is a little more expensive than that one.",py:"Zhè jiàn yīfu bǐ nà jiàn guì yìxiē."}],exercises:[{kind:"choice",q:"哥哥比我高___，他一米九，我一米六。",instr:"辨析",instrEn:"Pick the right one",body:"哥哥比我高___，他一米九，我一米六。",options:["得多","一点儿","很","非常"],answer:0,explain:"差三十厘米是很大的差别，用“得多”；“比”字句里不能用“很、非常”。",explainEn:"A 30 cm gap is big, so 得多; 很 and 非常 are not used in 比 sentences."},{kind:"choice",q:"这个比那个贵一点儿，___",instr:"完成",instrEn:"Complete the sentence",body:"这个比那个贵一点儿，___",options:["比那个贵得多。","比那个便宜。","只贵了五块钱。","跟那个一样贵。"],answer:2,explain:"“贵一点儿”表示差别很小，所以只贵五块钱；“贵得多”是差别大。",explainEn:"贵一点儿 means a small difference, so only five yuan; 贵得多 would be a big gap."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["今天比昨天热一些。","我比他很高。","他的房间比我的大多了。","坐飞机比坐火车快得多。"],answer:1,explain:"“比”字句的形容词前不能用“很”，可以说“我比他高得多”。",explainEn:"In a 比 sentence, no 很 before the adjective; say 我比他高得多."},{q:"翻译：This road is a little quieter than that one.",a:"这条路比那条路安静一点儿。",instr:"翻译",instrEn:"Translate",body:"This road is a little quieter than that one."}],note:"“很/非常”一般不能直接放在“比”字句的形容词前。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"A + bǐ + B + Adjective + yìdiǎnr / yìxiē / de duō / duō le = A is a bit / much more … than B",noteEn:"很/非常 normally can't go before the adjective in a 比 sentence.",typeEn:"Comparison"},{id:"3.10.2",name:"概数1：“一两个、两三天”等相邻数字",pinyin:"gàishù 1",type:"数量表达",explainEn:"Put two nearby numbers together to mean an approximate amount.",structure:"相邻数字 + 量词/名词",examples:[{zh:"我等一两分钟。",en:"I will wait one or two minutes.",py:"Wǒ děng yì liǎng fēnzhōng."},{zh:"他两三天以后回来。",en:"He will return in two or three days.",py:"Tā liǎng sān tiān yǐhòu huílai."},{zh:"我有四五个中国朋友。",en:"I have about four or five Chinese friends.",py:"Wǒ yǒu sì wǔ ge Zhōngguó péngyou."}],exercises:[{kind:"choice",q:"这件事我只说了___句，他就生气了。",instr:"辨析",instrEn:"Pick the right one",body:"这件事我只说了___句，他就生气了。",options:["二三","二两","两三个","两三"],answer:3,explain:"相邻数字表示大概时说“两三”，不说“二三”；“句”是量词，前面不能再加“个”。",explainEn:"For an approximate number say 两三, not 二三; 句 is already a measure word, so no 个."},{kind:"choice",q:"他每天睡五六个小时，___",instr:"完成",instrEn:"Complete the sentence",body:"他每天睡五六个小时，___",options:["常常觉得很累。","一共是十一个小时。","睡得比谁都多。","比十个小时还多。"],answer:0,explain:"“五六个小时”是大概五个或六个小时，不是五加六，所以常常觉得很累。",explainEn:"五六个小时 means about five or six hours, not 5 + 6, so he is often tired."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我去过两三次。","他三四天以后回来。","我有二三个好朋友。","我们等了七八分钟。"],answer:2,explain:"在量词前要用“两”，应说“我有两三个好朋友”。",explainEn:"Before a measure word use 两: 我有两三个好朋友."},{q:"翻译：two or three days",a:"两三天",instr:"翻译",instrEn:"Translate",body:"two or three days"}],note:"一般使用相邻数字，如“一两、两三、四五”。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:'consecutive numbers + measure word/Noun = roughly, e.g. "two or three"',noteEn:"Use adjacent numbers, e.g. 一两, 两三, 四五.",typeEn:"Quantity"}]},{num:11,title:"别忘了把空调关了",points:[{id:"3.11.1",name:"“把”字句1：A 把 B + V + ……",pinyin:"bǎ zì jù 1",type:"把字句",explainEn:"Use 把 to put a specific object before the verb and show what happens to it.",structure:"A + 把 + B + 动词 + 其他成分",examples:[{zh:"请把门关了。",en:"Please close the door.",py:"Qǐng bǎ mén guān le."},{zh:"我把作业写完了。",en:"I finished the homework.",py:"Wǒ bǎ zuòyè xiě wán le."},{zh:"别忘了把空调关了。",en:"Do not forget to turn off the air conditioner.",py:"Bié wàng le bǎ kōngtiáo guān le."}],exercises:[{kind:"choice",q:"请___门打开，房间里太热了。",instr:"辨析",instrEn:"Pick the right one",body:"请___门打开，房间里太热了。",options:["被","对","让","把"],answer:3,explain:"要对“门”做“打开”这个动作，用“把 + 东西 + 动词 + 其他”；“被”是被动，意思不对。",explainEn:"To do something to the door, use 把 + object + verb; 被 is passive and does not fit a request."},{kind:"choice",q:"我把那本书___。",instr:"完成",instrEn:"Complete the sentence",body:"我把那本书___。",options:["看","看过","喜欢","看完了"],answer:3,explain:"“把”字句的动词后面要有结果等其他成分，而且要是能处置东西的动作，“喜欢”不行。",explainEn:"A 把 verb needs something after it, like a result, and must act on the thing; 喜欢 cannot."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我把衣服洗了。","我把这本书没看完。","你把手机给我。","他把门关上了。"],answer:1,explain:"否定词要放在“把”前面，应说“我没把这本书看完”。",explainEn:"The negative goes before 把: 我没把这本书看完."},{q:"翻译：I drank up the milk.",a:"我把牛奶喝完了。",instr:"翻译",instrEn:"Translate",body:"I drank up the milk."}],note:"“把”后的宾语通常是明确、已知的事物；动词后一般不能什么都没有。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"A + bǎ + B + Verb + other elements = do sth to B (and change it)",noteEn:"The 把 object is usually definite/known, and the verb can't stand bare afterwards.",typeEn:"把 sentence"},{id:"3.11.2",name:"概数2：“左右”表示大约",pinyin:"zuǒyòu",type:"数量表达",explainEn:"Put 左右 after a number to mean “about / around”.",structure:"数字/数量 + 左右",examples:[{zh:"我八点左右到。",en:"I will arrive at around eight.",py:"Wǒ bā diǎn zuǒyòu dào."},{zh:"这里有二十个人左右。",en:"There are about twenty people here.",py:"Zhèlǐ yǒu èrshí ge rén zuǒyòu."},{zh:"他三十岁左右。",en:"He is around thirty years old.",py:"Tā sānshí suì zuǒyòu."}],exercises:[{kind:"choice",q:"从这儿到学校走路要二十分钟___。",instr:"辨析",instrEn:"Pick the right one",body:"从这儿到学校走路要二十分钟___。",options:["前后","以后","左右","多少"],answer:2,explain:"“左右”放在数量后面表示大概；“前后”用在时间点后面，“以后”是之后，“多少”是问数量。",explainEn:"左右 after an amount means “about”; 前后 goes with a point in time, 以后 means “after”, 多少 asks “how many”."},{kind:"choice",q:"我们七点左右见，___",instr:"完成",instrEn:"Complete the sentence",body:"我们七点左右见，___",options:["早几分钟晚几分钟都行。","一分钟也不能晚。","七点必须到。","必须七点以前到。"],answer:0,explain:"“七点左右”是大概七点，早一点儿晚一点儿都可以。",explainEn:"七点左右 means roughly seven, so a few minutes either way is fine."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他四十岁左右。","我们走了一个小时左右。","这本书三十块钱左右。","我左右七点起床。"],answer:3,explain:"“左右”要放在数量的后面，应说“我七点左右起床”。",explainEn:"左右 goes after the number: 我七点左右起床."},{q:"翻译：about twenty people",a:"二十个人左右",instr:"翻译",instrEn:"Translate",body:"about twenty people"}],note:"“左右”放在数量表达后面。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"number/quantity + zuǒyòu = about / around",noteEn:"左右 goes after the quantity.",typeEn:"Quantity"}]},{num:12,title:"把重要的东西放在我这儿吧",points:[{id:"3.12.1",name:"“才”和“就”的区别",pinyin:"cái / jiù",type:"副词",explainEn:"才 often means “not until / only then / late”. 就 often means “already / as early as / quickly”.",structure:"时间/条件 + 才/就 + 动词",examples:[{zh:"他九点才起床。",en:"He did not get up until nine.",py:"Tā jiǔ diǎn cái qǐchuáng."},{zh:"他六点就起床了。",en:"He got up as early as six.",py:"Tā liù diǎn jiù qǐchuáng le."},{zh:"我等了半小时，他才来。",en:"I waited half an hour before he came.",py:"Wǒ děng le bàn xiǎoshí, tā cái lái."}],exercises:[{kind:"choice",q:"电影七点开始，他七点半___到。",instr:"辨析",instrEn:"Pick the right one",body:"电影七点开始，他七点半___到。",options:["才","就","再","又"],answer:0,explain:"他到得比电影开始晚，表示晚用“才”；“就”表示早或快。",explainEn:"He arrived later than the start, so 才 (late); 就 would mean early."},{kind:"choice",q:"他六点就起床了，___",instr:"完成",instrEn:"Complete the sentence",body:"他六点就起床了，___",options:["起得太晚了。","又迟到了。","起得真早。","睡了很久才起。"],answer:2,explain:"“六点就起床了”表示起得早，所以说“起得真早”。",explainEn:"六点就起床了 means he got up early."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他八点才来。","我五分钟就做完了。","你怎么现在才回来？","他十点起床才。"],answer:3,explain:"“才”要放在动词前面，不能放在句末，应说“他十点才起床”。",explainEn:"才 goes before the verb, never at the end: 他十点才起床."},{q:"翻译：I was up as early as five this morning.",a:"我今天早上五点就起床了。",instr:"翻译",instrEn:"Translate",body:"I was up as early as five this morning."}],note:"“才”常让人感觉晚、慢、少；“就”常让人感觉早、快、容易。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"time/condition + cái / jiù + Verb = only then (late) vs already then (soon)",noteEn:"才 feels late/slow/few; 就 feels early/fast/easy.",typeEn:"Adverb"},{id:"3.12.2",name:"“把”字句2：把 B + V + 在/到/给……",pinyin:"bǎ zì jù 2",type:"把字句",explainEn:"Use 把 when an action moves an object to a place or person.",structure:"A + 把 + B + V + 在/到/给 + 地点/人",examples:[{zh:"请把书放在桌子上。",en:"Please put the book on the table.",py:"Qǐng bǎ shū fàng zài zhuōzi shang."},{zh:"我把照片发给朋友了。",en:"I sent the photo to my friend.",py:"Wǒ bǎ zhàopiàn fā gěi péngyou le."},{zh:"他把杯子拿到厨房去了。",en:"He took the cup to the kitchen.",py:"Tā bǎ bēizi ná dào chúfáng qù le."}],exercises:[{kind:"choice",q:"我把钱交___老师了。",instr:"辨析",instrEn:"Pick the right one",body:"我把钱交___老师了。",options:["在","给","到","对"],answer:1,explain:"把东西交到某人那里用“V + 给 + 人”；“在、到”后面要接地点，不直接接人。",explainEn:"To hand something to a person use V + 给 + person; 在 and 到 need a place."},{kind:"choice",q:"请把这个礼物送给___。",instr:"完成",instrEn:"Complete the sentence",body:"请把这个礼物送给___。",options:["北京","商店里","王老师","桌子上"],answer:2,explain:"“送给”后面要接人，不能接地点。",explainEn:"送给 must be followed by a person, not a place."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我把车开到楼下了。","他把箱子搬到二楼了。","我把衣服挂了在门后面。","请把那杯水拿给我。"],answer:2,explain:"“在”要紧跟在动词后面，“了”不能放中间，应说“我把衣服挂在门后面了”。",explainEn:"在 must follow the verb directly: 我把衣服挂在门后面了."},{q:"翻译：He put the bag in the car.",a:"他把包放在车里了。",instr:"翻译",instrEn:"Translate",body:"He put the bag in the car."}],note:"本课重点是“把”字句后出现地点或接受者：在、到、给。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"A + bǎ + B + V + zài/dào/gěi + place/person = put/move/give B to …",noteEn:"Focus: the 把 sentence with a place or recipient after the verb: 在/到/给.",typeEn:"把 sentence"}]},{num:13,title:"我是走回来的",points:[{id:"3.13.1",name:"复合趋向补语",pinyin:"fùhé qūxiàng bǔyǔ",type:"趋向补语",explainEn:"Use a direction word + 来/去 after a verb to show a more specific direction.",structure:"V + 上/下/进/出/回/过/起 + 来/去",examples:[{zh:"请走进来。",en:"Please walk in.",py:"Qǐng zǒu jìnlai."},{zh:"他跑出去了。",en:"He ran out.",py:"Tā pǎo chūqu le."},{zh:"我把书拿回来了。",en:"I brought the book back.",py:"Wǒ bǎ shū ná huílai le."}],exercises:[{kind:"choice",q:"我在楼下等你，你快走___吧。",instr:"辨析",instrEn:"Pick the right one",body:"我在楼下等你，你快走___吧。",options:["下去","上来","下来","上去"],answer:2,explain:"说话人在楼下，对方从楼上向说话人走，用“下来”。",explainEn:"The speaker is downstairs and the listener comes down toward him: 下来."},{kind:"choice",q:"他把书拿回来了，___",instr:"完成",instrEn:"Complete the sentence",body:"他把书拿回来了，___",options:["现在书在我这儿。","书还在图书馆。","书在他朋友那儿。","书还没拿到。"],answer:0,explain:"“拿回来”表示拿回到说话人这里，所以书现在在“我这儿”。",explainEn:"拿回来 means brought back to the speaker, so the book is here with me."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他从楼上走下来了。","老师走进教室来了。","他跑回家去了。","他走进来教室了。"],answer:3,explain:"表示地点的宾语要放在“来/去”前面，应说“他走进教室来了”。",explainEn:"A place object goes before 来/去: 他走进教室来了."},{q:"翻译：The bird flew out of the room.",a:"鸟从房间里飞出去了。",instr:"翻译",instrEn:"Translate",body:"The bird flew out of the room."}],note:"“来”朝说话人方向，“去”离开说话人方向。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"V + shàng/xià/jìn/chū/huí/guò/qǐ + lái/qù = compound directional complement",noteEn:"来 is toward the speaker; 去 is away from the speaker.",typeEn:"Directional compl."},{id:"3.13.2",name:"“一边……一边……”表示同时做两件事",pinyin:"yìbiān ... yìbiān ...",type:"并列结构",explainEn:"Use 一边…一边… for two actions happening at the same time.",structure:"一边 + V1，一边 + V2",examples:[{zh:"我一边吃饭，一边看电视。",en:"I eat while watching TV.",py:"Wǒ yìbiān chī fàn, yìbiān kàn diànshì."},{zh:"她一边走路，一边听音乐。",en:"She listens to music while walking.",py:"Tā yìbiān zǒulù, yìbiān tīng yīnyuè."},{zh:"我们一边喝茶，一边聊天。",en:"We drink tea and chat at the same time.",py:"Wǒmen yìbiān hē chá, yìbiān liáotiān."}],exercises:[{kind:"choice",q:"我们___走路一边聊天吧。",instr:"辨析",instrEn:"Pick the right one",body:"我们___走路一边聊天吧。",options:["一起","一边","一样","一点"],answer:1,explain:"两个动作同时进行，要用“一边……一边……”，两个“一边”都要有。",explainEn:"For two actions at once use 一边…一边…, with both 一边."},{kind:"choice",q:"他一边开车，一边___。",instr:"完成",instrEn:"Complete the sentence",body:"他一边开车，一边___。",options:["听音乐","打完了电话","高兴","到了公司"],answer:0,explain:"“一边”后面要接能一直做下去的动作；“打完了电话、到了公司”一下子就完了，“高兴”不是动作。",explainEn:"一边 needs an ongoing action; 打完了电话 and 到了公司 are finished at once, and 高兴 is not an action."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["她一边唱歌一边跳舞。","我一边听，一边写。","我一边到了家，一边给你打电话。","我们一边吃饭一边聊天。"],answer:2,explain:"“到了家”一下子就完成，不能和别的动作同时进行，可说“我到了家就给你打电话”。",explainEn:"到了家 is instant and cannot overlap; say 我到了家就给你打电话."},{q:"翻译：He reads the newspaper while eating breakfast.",a:"他一边吃早饭，一边看报纸。",instr:"翻译",instrEn:"Translate",body:"He reads the newspaper while eating breakfast."}],note:"两个动作通常可以同时进行。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"yìbiān + V1, yìbiān + V2 = do V1 and V2 at the same time",noteEn:"The two actions usually happen at the same time.",typeEn:"Coordinate structure"}]},{num:14,title:"你把水果拿过来",points:[{id:"3.14.1",name:"“把”字句3：把 B + V + 结果/趋向补语",pinyin:"bǎ zì jù 3",type:"把字句",explainEn:"Use 把 + object + verb + result/direction complement to show the result or movement of the object.",structure:"A + 把 + B + V + 结果补语/趋向补语",examples:[{zh:"请把水果拿过来。",en:"Please bring the fruit over here.",py:"Qǐng bǎ shuǐguǒ ná guòlai."},{zh:"我把房间打扫干净了。",en:"I cleaned the room.",py:"Wǒ bǎ fángjiān dǎsǎo gānjìng le."},{zh:"他把作业做完了。",en:"He finished the homework.",py:"Tā bǎ zuòyè zuò wán le."}],exercises:[{kind:"choice",q:"外面很冷，快把衣服穿___。",instr:"辨析",instrEn:"Pick the right one",body:"外面很冷，快把衣服穿___。",options:["起","出","上","开"],answer:2,explain:"“穿上”表示衣服穿到身上了；“穿起、穿出、穿开”不能这样用。",explainEn:"穿上 means the clothes are on; 穿起, 穿出 and 穿开 are not used this way."},{kind:"choice",q:"他把我的名字写错了，___",instr:"完成",instrEn:"Complete the sentence",body:"他把我的名字写错了，___",options:["一个字也没写错。","我让他再写一次。","写得很好看。","老师说他写得很对。"],answer:1,explain:"“写错了”表示写的结果不对，所以要再写一次；“没写错、写得很对”和“写错”意思相反。",explainEn:'写错了 means the result is wrong, so he has to write it again; "not wrong" or "correct" contradicts it.'},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他把杯子拿起来了。","请把手洗干净。","我把字写错了。","我把房间打扫了干净。"],answer:3,explain:"结果补语要紧跟在动词后面，“了”放在补语后，应说“我把房间打扫干净了”。",explainEn:"The result complement follows the verb directly: 我把房间打扫干净了."},{q:"翻译：Please write your name clearly.",a:"请把你的名字写清楚。",instr:"翻译",instrEn:"Translate",body:"Please write your name clearly."}],note:"本课强调“把”字句中的结果补语或趋向补语。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"A + bǎ + B + V + resultative/directional complement = handle B with that result",noteEn:"Focus: a result or directional complement in the 把 sentence.",typeEn:"把 sentence"},{id:"3.14.2",name:"“先……，再/又……，然后……”表示动作顺序",pinyin:"xiān ... zài/yòu ... ránhòu ...",type:"顺序结构",explainEn:"Use 先…再/又…然后… to show the order of several actions.",structure:"先 + V1，再/又 + V2，然后 + V3",examples:[{zh:"我先吃饭，再做作业。",en:"First I eat, then I do homework.",py:"Wǒ xiān chī fàn, zài zuò zuòyè."},{zh:"先洗手，然后吃饭。",en:"Wash your hands first, then eat.",py:"Xiān xǐ shǒu, ránhòu chī fàn."},{zh:"他先去了商店，又去了银行，然后回家。",en:"He first went to the shop, then the bank, and then went home.",py:"Tā xiān qù le shāngdiàn, yòu qù le yínháng, ránhòu huí jiā."}],exercises:[{kind:"choice",q:"我们先去买票，___进去看电影。",instr:"辨析",instrEn:"Pick the right one",body:"我们先去买票，___进去看电影。",options:["又","再","才","还"],answer:1,explain:"“先……再……”说还没做的事的顺序；“又”用在已经发生的事。",explainEn:"先…再… gives the order of planned actions; 又 is for things already done."},{kind:"choice",q:"你先做作业，___",instr:"完成",instrEn:"Complete the sentence",body:"你先做作业，___",options:["然后先看电视。","以前看电视。","先看电视吧。","然后再看电视。"],answer:3,explain:"“先”后面接“然后/再”说下一步，不能再用一个“先”。",explainEn:"After 先 the next step takes 然后/再, not a second 先."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我们先吃饭，再去看电影。","他先洗了澡，然后睡觉了。","我先买菜，然后先做饭。","先听老师说，然后自己做。"],answer:2,explain:"第二步不能再用“先”，应说“我先买菜，然后做饭”。",explainEn:"The second step cannot use 先 again: 我先买菜，然后做饭."},{q:"翻译：Listen first, then answer.",a:"先听一听，然后再回答。",instr:"翻译",instrEn:"Translate",body:"Listen first, then answer."}],note:"“再”常用于下一步；“又”可用于叙述已经发生的第二个动作。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"xiān + V1, zài/yòu + V2, ránhòu + V3 = first …, then …, after that …",noteEn:"再 is for the next step; 又 can narrate a second action that already happened.",typeEn:"Sequence structure"}]},{num:15,title:"其他都没什么问题",points:[{id:"3.15.1",name:"“除了……以外，都/还/也……”表示范围",pinyin:"chúle ... yǐwài",type:"范围结构",explainEn:"Use 除了…以外 to mean “except for…” or “besides…”. 都 shows exception; 还/也 adds something.",structure:"除了 + X + 以外，其他 + 都… / 还/也…",examples:[{zh:"除了我以外，大家都来了。",en:"Everyone came except me.",py:"Chúle wǒ yǐwài, dàjiā dōu lái le."},{zh:"除了汉语以外，我还学英语。",en:"Besides Chinese, I also study English.",py:"Chúle Hànyǔ yǐwài, wǒ hái xué Yīngyǔ."},{zh:"除了苹果，我也喜欢西瓜。",en:"Besides apples, I also like watermelon.",py:"Chúle píngguǒ, wǒ yě xǐhuan xīguā."}],exercises:[{kind:"choice",q:"除了小王，别人___去过，只有他没去过。",instr:"辨析",instrEn:"Pick the right one",body:"除了小王，别人___去过，只有他没去过。",options:["还","也","都","就"],answer:2,explain:"这里是排除小王，别人全部去过，用“都”；“还、也”表示另外加上。",explainEn:"Here 小王 is excluded and everyone else went, so 都; 还/也 would add something."},{kind:"choice",q:"除了星期一以外，___",instr:"完成",instrEn:"Complete the sentence",body:"除了星期一以外，___",options:["他每天都很忙。","他星期一很忙。","他星期一也很忙。","他只有星期一很忙。"],answer:0,explain:"“除了……以外，都……”表示把前面的去掉，其余全部一样，所以是“每天都很忙”；后面不能再说星期一。",explainEn:"除了…以外，都… excludes the first item and says the rest are all the same: every other day is busy; the second part cannot be about Monday again."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["除了米饭以外，我都喜欢吃面条。","除了他，大家都知道了。","除了游泳，我还喜欢跑步。","除了星期天以外，他每天都上班。"],answer:0,explain:"这里是在米饭以外再加面条，应用“还/也”：“除了米饭以外，我还喜欢吃面条”。",explainEn:"This adds noodles to rice, so use 还/也: 除了米饭以外，我还喜欢吃面条."},{q:"翻译：Besides my mom, my dad came too.",a:"除了妈妈以外，爸爸也来了。",instr:"翻译",instrEn:"Translate",body:"Besides my mom, my dad came too."}],note:"“都”常表示排除一个范围；“还/也”常表示在原有内容上增加。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"chúle + X + yǐwài, qítā + dōu… / hái/yě… = apart from X, …",noteEn:"都 excludes (except…); 还/也 add one more item.",typeEn:"Scope structure"},{id:"3.15.2",name:"疑问代词活用2：“什么”表示不确定的人或事物",pinyin:"yíwèn dàicí huóyòng 2",type:"代词结构",explainEn:"Use 什么 in a non-question to mean “something / anything” when the thing is not specific.",structure:"（没）什么 + 名词 / 有什么 + 名词",examples:[{zh:"我没什么问题。",en:"I do not have any questions.",py:"Wǒ méi shénme wèntí."},{zh:"你想喝点儿什么？",en:"Would you like something to drink?",py:"Nǐ xiǎng hē diǎnr shénme?"},{zh:"有什么事给我打电话。",en:"If there is anything, call me.",py:"Yǒu shénme shì gěi wǒ dǎ diànhuà."}],exercises:[{kind:"choice",q:"你别客气，有___问题就问我。",instr:"辨析",instrEn:"Pick the right one",body:"你别客气，有___问题就问我。",options:["哪","怎么","谁","什么"],answer:3,explain:"“有什么 + 名词”表示不确定的任何东西；“哪、怎么、谁”不能直接放在“问题”前面。",explainEn:"有什么 + noun means “any …”; 哪, 怎么 and 谁 cannot go before 问题 like this."},{kind:"choice",q:"我没什么事，___",instr:"完成",instrEn:"Complete the sentence",body:"我没什么事，___",options:["就是想看看你。","有很多事要做。","有一件大事。","今天特别忙。"],answer:0,explain:"“没什么事”意思是没有重要的事，所以只是来看看你。",explainEn:"没什么事 means nothing in particular, so I just came to see you."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我不想吃什么。","你有什么事吗？","冰箱里没什么吃的。","我没有问题什么。"],answer:3,explain:"“什么”要放在名词前面，应说“我没有什么问题”。",explainEn:"什么 goes before the noun: 我没有什么问题."},{q:"翻译：Is there anything to eat at home?",a:"家里有什么吃的吗？",instr:"翻译",instrEn:"Translate",body:"Is there anything to eat at home?"}],note:"这里“什么”不是要求一个确定答案，而表示不确定的人或事物。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"(méi) shénme + Noun / yǒu shénme + Noun = not much … / what … is there?",noteEn:`Here 什么 doesn't ask for a definite answer; it means "something/anything".`,typeEn:"Pronoun structure"},{id:"3.15.3",name:"“极了”表示程度很高",pinyin:"jí le",type:"程度表达",explainEn:"Put 极了 after an adjective to mean “extremely / very”.",structure:"形容词 + 极了",examples:[{zh:"今天热极了。",en:"It is extremely hot today.",py:"Jīntiān rè jí le."},{zh:"这个地方漂亮极了。",en:"This place is extremely beautiful.",py:"Zhège dìfang piàoliang jí le."},{zh:"他高兴极了。",en:"He is extremely happy.",py:"Tā gāoxìng jí le."}],exercises:[{kind:"choice",q:"听了他的话，大家都高兴___。",instr:"辨析",instrEn:"Pick the right one",body:"听了他的话，大家都高兴___。",options:["很","非常","太","极了"],answer:3,explain:"表示程度很高的词放在形容词后面的只有“极了”；“很、非常、太”要放在形容词前面。",explainEn:"Of these, only 极了 goes after the adjective; 很, 非常 and 太 go before it."},{kind:"choice",q:"这儿的冬天冷极了，___",instr:"完成",instrEn:"Complete the sentence",body:"这儿的冬天冷极了，___",options:["只是有一点儿冷。","比秋天冷一点儿。","不用穿很多衣服。","出去要多穿几件衣服。"],answer:3,explain:"“冷极了”是非常冷，所以出去要多穿衣服；“有一点儿冷、冷一点儿、不用穿很多”都只是有点儿冷，跟“极了”不合。",explainEn:"冷极了 means extremely cold, so you must wear more clothes; the others mean only a little cold, which does not fit 极了."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这个菜好吃极了。","今天冷极了。","他的房间干净极了。","他很好极了。"],answer:3,explain:"“极了”已经表示程度很高，前面不能再加“很”，应说“他好极了”。",explainEn:"极了 already means “extremely”, so drop 很: 他好极了."},{q:"翻译：The weather is extremely good today.",a:"今天天气好极了。",instr:"翻译",instrEn:"Translate",body:"The weather is extremely good today."}],note:"“极了”放在形容词后面，程度比“很”强。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"Adjective + jí le = extremely …",noteEn:"极了 goes after an adjective and is stronger than 很.",typeEn:"Degree"}]},{num:16,title:"我现在累得下了班就想睡觉",points:[{id:"3.16.1",name:"“如果……（的话），就……”表示条件",pinyin:"rúguǒ ... (dehuà), jiù ...",type:"条件复句",explainEn:"Use 如果…就… to mean “if… then…”. 的话 can be added after the condition.",structure:"如果 + 条件 +（的话），主语 + 就 + 结果",examples:[{zh:"如果明天下雨，我们就不去了。",en:"If it rains tomorrow, we will not go.",py:"Rúguǒ míngtiān xià yǔ, wǒmen jiù bú qù le."},{zh:"如果你累了，就休息一下。",en:"If you are tired, take a rest.",py:"Rúguǒ nǐ lèi le, jiù xiūxi yíxià."},{zh:"如果有时间的话，我就去看你。",en:"If I have time, I will go see you.",py:"Rúguǒ yǒu shíjiān dehuà, wǒ jiù qù kàn nǐ."}],exercises:[{kind:"choice",q:"如果你明天有空，我们___去看电影吧。",instr:"辨析",instrEn:"Pick the right one",body:"如果你明天有空，我们___去看电影吧。",options:["才","刚","又","就"],answer:3,explain:"“如果……就……”，条件后面用“就”说结果；“才”用在“只有……才……”，“又、刚”不能说将来的打算。",explainEn:"如果…就…: the result after the condition takes 就; 才 goes with 只有…才…, and 又/刚 cannot express a future plan."},{kind:"choice",q:"如果明天很冷，___",instr:"完成",instrEn:"Complete the sentence",body:"如果明天很冷，___",options:["但是我们还去爬山。","我们就不去爬山了。","所以我们不去爬山。","可是我们去爬山了。"],answer:1,explain:"“如果”后面用“就”说结果；“但是、可是”用在“虽然”句里，“所以”用在“因为”句里。",explainEn:"如果 pairs with 就; 但是/可是 go with 虽然, 所以 goes with 因为."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["如果你饿了，就先吃吧。","如果你有问题的话，就问我。","如果你想去，我就带你去。","如果天气好，我们才去公园。"],answer:3,explain:"“如果”要和“就”搭配，应说“如果天气好，我们就去公园”。",explainEn:"如果 pairs with 就: 如果天气好，我们就去公园."},{q:"翻译：If you have time, come to my home.",a:"如果你有时间，就来我家吧。",instr:"翻译",instrEn:"Translate",body:"If you have time, come to my home."}],note:"“的话”可以省略，但“如果……就……”是最清楚的基本结构。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"rúguǒ + condition + (dehuà), Subject + jiù + result = if …, then …",noteEn:"的话 can be dropped, but 如果…就… is the clearest basic pattern.",typeEn:"Conditional"},{id:"3.16.2",name:"复杂的状态补语：“形容词/动词 + 得 + 动词词组”",pinyin:"fùzá de zhuàngtài bǔyǔ",type:"状态补语",explainEn:"Use adjective/verb + 得 + a phrase to show a strong degree and its result.",structure:"形容词/动词 + 得 + 动词词组/小句",examples:[{zh:"我累得不想说话。",en:"I am so tired that I do not want to talk.",py:"Wǒ lèi de bù xiǎng shuōhuà."},{zh:"他忙得没时间吃饭。",en:"He is so busy that he has no time to eat.",py:"Tā máng de méi shíjiān chī fàn."},{zh:"孩子高兴得又唱又跳。",en:"The child is so happy that he sings and jumps.",py:"Háizi gāoxìng de yòu chàng yòu tiào."}],exercises:[{kind:"choice",q:"我今天累___一句话也不想说。",instr:"辨析",instrEn:"Pick the right one",body:"我今天累___一句话也不想说。",options:["得","地","的","着"],answer:0,explain:"形容词后面接表示程度或结果的部分要用“得”：“累得一句话也不想说”；“地”放在动词前面说怎么做，“着、的”也不能这样用。",explainEn:"After an adjective, a degree/result part needs 得: 累得一句话也不想说; 地 marks how an action is done, and 着/的 do not work here."},{kind:"choice",q:"我饿得___。",instr:"完成",instrEn:"Complete the sentence",body:"我饿得___。",options:["吃了很多","很饱了","吃不下饭","走不动了"],answer:3,explain:"“饿得……”后面说因为很饿出现的情况，饿得走不动；其他都跟“饿”不合。",explainEn:"饿得… gives what hunger causes: too hungry to walk; the others do not follow from hunger."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["他忙地没时间吃饭。","他累得不想动。","她急得哭了。","我们笑得说不出话来。"],answer:0,explain:"形容词后面接补语要用“得”，不是“地”，应说“他忙得没时间吃饭”。",explainEn:"Use 得, not 地, after the adjective: 他忙得没时间吃饭."},{q:"翻译：She was so tired that she fell asleep right away.",a:"她累得马上就睡着了。",instr:"翻译",instrEn:"Translate",body:"She was so tired that she fell asleep right away."}],note:"“得”后面不是简单形容词，而可以是一整个短语或小句。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"Adjective/Verb + de + verb phrase/clause = … to the point that …",noteEn:"After 得 you can have a whole phrase or clause, not just one adjective.",typeEn:"State complement"},{id:"3.16.3",name:"单音节形容词重叠：“AA的”",pinyin:"AA de",type:"形容词重叠",explainEn:"Repeat a one-syllable adjective as AA的 to describe a vivid characteristic.",structure:"单音节形容词 + 重叠 + 的",examples:[{zh:"她的眼睛大大的。",en:"Her eyes are big.",py:"Tā de yǎnjing dàdà de."},{zh:"这个孩子胖胖的。",en:"This child is chubby.",py:"Zhège háizi pàngpàng de."},{zh:"她有长长的头发。",en:"She has long hair.",py:"Tā yǒu chángcháng de tóufa."}],exercises:[{kind:"choice",q:"我妹妹有一双___眼睛。",instr:"辨析",instrEn:"Pick the right one",body:"我妹妹有一双___眼睛。",options:["大大的","很大","大大","大大地"],answer:0,explain:"重叠形容词放在名词前要加“的”：“大大的眼睛”；“很大”后面也要“的”，“地”用在动词前。",explainEn:"A reduplicated adjective before a noun needs 的: 大大的眼睛; 很大 also needs 的, and 地 goes before verbs."},{kind:"choice",q:"房间里静静的，___",instr:"完成",instrEn:"Complete the sentence",body:"房间里静静的，___",options:["大家都在大声说话。","音乐的声音很大。","一个人也没有。","孩子们在唱歌跳舞。"],answer:2,explain:"“静静的”是很安静的样子，所以房间里没有人；其他都很热闹。",explainEn:"静静的 paints a very quiet room, so nobody is there; the others are noisy."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["她的手小小的。","他有一个高高的鼻子。","他的个子很高高的。","今天的天蓝蓝的。"],answer:2,explain:"重叠形容词已经有程度的意思，前面不能加“很”，应说“他的个子高高的”。",explainEn:"A reduplicated adjective already shows degree, so no 很: 他的个子高高的."},{q:"翻译：Her hair is nice and black.",a:"她的头发黑黑的。",instr:"翻译",instrEn:"Translate",body:"Her hair is nice and black."}],note:"常用来描写外貌和事物特点，语气生动。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"monosyllabic Adjective + reduplicated + de = vivid descriptive form, e.g. hónghóng de",noteEn:"Often describes looks and features, in a vivid tone.",typeEn:"Adjective redup."}]},{num:17,title:"谁都有办法看好你的“病”",points:[{id:"3.17.1",name:"双音节动词重叠：“ABAB”",pinyin:"ABAB",type:"动词重叠",explainEn:"Repeat a two-syllable verb as ABAB to mean doing it briefly or trying it.",structure:"双音节动词 AB → ABAB",examples:[{zh:"我们休息休息吧。",en:"Let us rest for a while.",py:"Wǒmen xiūxi xiūxi ba."},{zh:"你介绍介绍这个地方吧。",en:"Please introduce this place a little.",py:"Nǐ jièshào jièshào zhège dìfang ba."},{zh:"我想练习练习汉语。",en:"I want to practice Chinese for a bit.",py:"Wǒ xiǎng liànxí liànxí Hànyǔ."}],exercises:[{kind:"choice",q:"考试以前，我们一起___吧。",instr:"辨析",instrEn:"Pick the right one",body:"考试以前，我们一起___吧。",options:["复复习习","复习一复习","复习复习","复习了复习"],answer:2,explain:"双音节动词重叠是ABAB：“复习复习”；中间不能加“一”，也不能说“AABB”。",explainEn:"Two-syllable verbs repeat as ABAB: 复习复习; no 一 in the middle and no AABB form."},{kind:"choice",q:"我们休息休息，___",instr:"完成",instrEn:"Complete the sentence",body:"我们休息休息，___",options:["休息三个星期。","明年再走吧。","十分钟以后再走。","以后不走了。"],answer:2,explain:"动词重叠表示时间短，所以只休息一会儿，十分钟后再走。",explainEn:"Verb reduplication means a short time, so just a ten-minute rest."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["你给我们介绍介绍吧。","周末我想在家休息休息。","你应该好好儿锻炼锻炼身体。","我昨天打扫打扫了房间。"],answer:3,explain:"双音节动词重叠后面不能直接加“了”，可说“我昨天打扫了一下房间”。",explainEn:"A reduplicated two-syllable verb cannot take 了 after it; say 我昨天打扫了一下房间."},{q:"翻译：Let us practice Chinese for a bit.",a:"我们练习练习汉语吧。",instr:"翻译",instrEn:"Translate",body:"Let us practice Chinese for a bit."}],note:"双音节动词一般用ABAB，不说AABB。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"disyllabic Verb AB → ABAB = do sth a little / for a while",noteEn:"Two-syllable verbs reduplicate as ABAB, not AABB.",typeEn:"Verb reduplication"},{id:"3.17.2",name:"疑问代词活用3：疑问代词 + 都/也……表示任指",pinyin:"yíwèn dàicí huóyòng 3",type:"代词结构",explainEn:"Use 谁/什么/哪儿/怎么 + 都/也 to mean “everyone / everything / anywhere / any way”.",structure:"疑问代词 + 都/也 + 谓语",examples:[{zh:"谁都喜欢她。",en:"Everyone likes her.",py:"Shéi dōu xǐhuan tā."},{zh:"我什么都吃。",en:"I eat everything.",py:"Wǒ shénme dōu chī."},{zh:"我们去哪儿都可以。",en:"We can go anywhere.",py:"Wǒmen qù nǎr dōu kěyǐ."}],exercises:[{kind:"choice",q:"他太累了，___也不想去，只想在家睡觉。",instr:"辨析",instrEn:"Pick the right one",body:"他太累了，___也不想去，只想在家睡觉。",options:["谁","什么","多少","哪儿"],answer:3,explain:"说的是不想去任何地方，用“哪儿 + 也”；“谁、什么、多少”不能表示地方。",explainEn:"Not wanting to go anywhere is 哪儿也不想去; 谁, 什么 and 多少 are not places."},{kind:"choice",q:"我谁都不认识，___",instr:"完成",instrEn:"Complete the sentence",body:"我谁都不认识，___",options:["大家都是我的好朋友。","每个人我都认识。","你能给我介绍一下吗？","他们都认识我很久了。"],answer:2,explain:"“谁都不认识”是一个人也不认识，所以要请别人介绍。",explainEn:"谁都不认识 means I know nobody here, so I ask to be introduced."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["谁都想去。","他哪儿也不想去。","我怎么也找不到我的手机。","我什么不想吃。"],answer:3,explain:"疑问代词表示任指，后面要加“都/也”，应说“我什么都不想吃”。",explainEn:"For “any/every”, the question word needs 都/也: 我什么都不想吃."},{q:"翻译：Nobody knows where he went.",a:"谁都不知道他去哪儿了。",instr:"翻译",instrEn:"Translate",body:"Nobody knows where he went."}],note:"这些疑问代词不表示疑问，而表示一个范围里的“每一个/任何一个”。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"question word + dōu/yě + predicate = every / any one of them …",noteEn:`Here the question words aren't questions; they mean "every/any one".`,typeEn:"Pronoun structure"}]},{num:18,title:"我相信他们会同意的",points:[{id:"3.18.1",name:"“只要……，就……”表示充分条件",pinyin:"zhǐyào ... jiù ...",type:"条件复句",explainEn:"Use 只要…就… to mean “as long as… then…”.",structure:"只要 + 条件，就 + 结果",examples:[{zh:"只要你努力，就会进步。",en:"As long as you work hard, you will improve.",py:"Zhǐyào nǐ nǔlì, jiù huì jìnbù."},{zh:"只要不下雨，我们就去。",en:"As long as it does not rain, we will go.",py:"Zhǐyào bú xià yǔ, wǒmen jiù qù."},{zh:"只要有时间，我就运动。",en:"As long as I have time, I exercise.",py:"Zhǐyào yǒu shíjiān, wǒ jiù yùndòng."}],exercises:[{kind:"choice",q:"只要你多练习，你的汉语___会越来越好。",instr:"辨析",instrEn:"Pick the right one",body:"只要你多练习，你的汉语___会越来越好。",options:["才","再","都","就"],answer:3,explain:"“只要”和“就”搭配，表示有这个条件就够了；“才”和“只有”搭配，“再、都”不能这样用。",explainEn:"只要 pairs with 就: this condition is enough; 才 pairs with 只有, and 再/都 do not fit."},{kind:"choice",q:"只要天气好，___",instr:"完成",instrEn:"Complete the sentence",body:"只要天气好，___",options:["我才去爬山。","我也不去爬山。","我就去爬山。","但是我不去爬山。"],answer:2,explain:"“只要”表示有这个条件就够了，后面用“就”说结果。",explainEn:"只要 means this condition is enough, and the result takes 就."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["只要你喜欢，就买吧。","只要有空，他就去看电影。","只要努力，你就能学好。","只要多听多说，才能学好汉语。"],answer:3,explain:"“只要”要和“就”搭配，应说“只要多听多说，就能学好汉语”。",explainEn:"只要 pairs with 就: 只要多听多说，就能学好汉语."},{q:"翻译：As long as you come, I will be happy.",a:"只要你来，我就很高兴。",instr:"翻译",instrEn:"Translate",body:"As long as you come, I will be happy."}],note:"“只要”强调这个条件一满足，后面的结果就可以发生。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"zhǐyào + condition, jiù + result = as long as …, then …",noteEn:"只要 stresses that once the condition is met, the result can happen.",typeEn:"Conditional"},{id:"3.18.2",name:"介词“关于”表示“关于/有关”",pinyin:"guānyú",type:"介词",explainEn:"Use 关于 before a topic to mean “about / concerning”.",structure:"关于 + 话题 +（的）+ 名词/句子",examples:[{zh:"关于这个问题，我想再说几句。",en:"I want to say a little more about this question.",py:"Guānyú zhège wèntí, wǒ xiǎng zài shuō jǐ jù."},{zh:"这是一本关于中国文化的书。",en:"This is a book about Chinese culture.",py:"Zhè shì yì běn guānyú Zhōngguó wénhuà de shū."},{zh:"关于明天的考试，老师说了很多。",en:"The teacher said a lot about tomorrow’s test.",py:"Guānyú míngtiān de kǎoshì, lǎoshī shuō le hěn duō."}],exercises:[{kind:"choice",q:"这是一个___熊猫的故事。",instr:"辨析",instrEn:"Pick the right one",body:"这是一个___熊猫的故事。",options:["关于","对于","对","跟"],answer:0,explain:"说故事的内容是什么，用“关于……的 + 名词”；“对于、对、跟”不能这样修饰名词。",explainEn:"To say what a story is about, use 关于…的 + noun; 对于, 对 and 跟 cannot do this."},{kind:"choice",q:"我想借一本关于中国历史___书。",instr:"完成",instrEn:"Complete the sentence",body:"我想借一本关于中国历史___书。",options:["地","的","得","了"],answer:1,explain:"“关于……”放在名词前面时，要加“的”：“关于中国历史的书”。",explainEn:"When 关于… modifies a noun, add 的: 关于中国历史的书."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["关于这个问题，我们明天再说。","我看了一本关于历史的书。","我关于中国很感兴趣。","关于考试的事，你问老师吧。"],answer:2,explain:"表示兴趣的对象要用“对”，应说“我对中国很感兴趣”。",explainEn:"Interest takes 对, not 关于: 我对中国很感兴趣."},{q:"翻译：a book about Chinese culture",a:"一本关于中国文化的书",instr:"翻译",instrEn:"Translate",body:"a book about Chinese culture"}],note:"“关于 + 话题”常放在句首；修饰名词时常用“关于……的 + 名词”。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"guānyú + topic + (de) + Noun/Sentence = about / concerning …",noteEn:"关于 + topic often opens the sentence; to modify a noun use 关于…的 + noun.",typeEn:"Preposition"}]},{num:19,title:"你没看出来吗？",points:[{id:"3.19.1",name:"趋向补语的引申义：“出来 / 下来 / 起来”",pinyin:"qūxiàng bǔyǔ de yǐnshēnyì",type:"趋向补语",explainEn:"Direction complements can have extended meanings: 出来 can show creation/recognition, 下来 a change becoming calmer/slower, and 起来 recalling.",structure:"V + 出来 / Adj-V + 下来 / V + 起来",examples:[{zh:"我想出来一个好办法。",en:"I came up with a good idea.",py:"Wǒ xiǎng chūlai yí ge hǎo bànfǎ."},{zh:"你看出来他是谁了吗？",en:"Did you recognize who he is?",py:"Nǐ kàn chūlai tā shì shéi le ma?"},{zh:"我想起来他的名字了。",en:"I remembered his name.",py:"Wǒ xiǎng qǐlai tā de míngzi le."}],exercises:[{kind:"choice",q:"老师一进来，教室里马上安静___了。",instr:"辨析",instrEn:"Pick the right one",body:"老师一进来，教室里马上安静___了。",options:["起来","下来","出来","下去"],answer:1,explain:"“下来”表示从动到静、从吵到安静；“起来”多表示开始变强，“出来”表示出现，“下去”表示继续。",explainEn:"下来 shows a change from noisy to quiet; 起来 usually means starting to become stronger, 出来 means appearing, 下去 means continuing."},{kind:"choice",q:"这个办法是他想出来的，___",instr:"完成",instrEn:"Complete the sentence",body:"这个办法是他想出来的，___",options:["他是从书上看到的。","别人都没想到。","是老师告诉他的。","他以前听说过。"],answer:1,explain:"“想出来”表示自己想到一个新的东西，所以是他自己想到的，不是从别处知道的。",explainEn:"想出来 means coming up with something new oneself, not learning it from someone else."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["我想起来了，他叫小李。","你看出来他不高兴了吗？","天慢慢黑下来了。","你听起来这是谁的声音吗？"],answer:3,explain:"听了以后认出来是谁，要用“出来”，应说“你听出来这是谁的声音了吗？”。",explainEn:"To recognize something by hearing, use 出来: 你听出来这是谁的声音了吗？"},{q:"翻译：I remembered where I put my phone.",a:"我想起来手机放在哪儿了。",instr:"翻译",instrEn:"Translate",body:"I remembered where I put my phone."}],note:"HSK3重点掌握“出来=产生/识别”，“下来=状态由强到弱/由动到静”，“起来=回忆有结果”。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"V + chūlai / Adj-V + xiàlai / V + qǐlai = figure out / calm down / start doing",noteEn:"Focus: 出来 = produce/identify, 下来 = fading/settling, 起来 = successful recall.",typeEn:"Directional compl."},{id:"3.19.2",name:"“使、叫、让”表示致使",pinyin:"shǐ / jiào / ràng",type:"兼语句",explainEn:"Use 使/叫/让 + person/thing + verb/adjective to mean “make / let”.",structure:"使 / 叫 / 让 + 人/事物 + 谓语",examples:[{zh:"这件事让我很高兴。",en:"This makes me very happy.",py:"Zhè jiàn shì ràng wǒ hěn gāoxìng."},{zh:"妈妈让我早点儿回家。",en:"Mom makes/asks me to go home early.",py:"Māma ràng wǒ zǎo diǎnr huí jiā."},{zh:"运动使身体更健康。",en:"Exercise makes the body healthier.",py:"Yùndòng shǐ shēntǐ gèng jiànkāng."}],exercises:[{kind:"choice",q:"老师___我们明天早点儿来。",instr:"辨析",instrEn:"Pick the right one",body:"老师___我们明天早点儿来。",options:["使","被","让","给"],answer:2,explain:"要求别人做事用“让/叫”；“使”多用在书面语，表示引起一种情况，不用在要求别人做事。",explainEn:"For asking someone to do something use 让/叫; 使 is formal and means “cause a state”, not “tell someone to”."},{kind:"choice",q:"这次旅行使___。",instr:"完成",instrEn:"Complete the sentence",body:"这次旅行使___。",options:["我更了解中国了","我明天去北京","我们早点儿出发","他去买火车票"],answer:0,explain:"“使”表示引起一种变化或状态，所以接“更了解中国了”；要求别人去做某件事要用“让/叫”。",explainEn:"使 means “cause a change of state”, so 我更了解中国了 fits; telling someone to do something needs 让/叫."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["这件事让我很生气。","老师叫我们回答问题。","运动使我更健康了。","妈妈使我去买东西。"],answer:3,explain:"要求别人做事用“让”或“叫”，“使”不这样用，应说“妈妈让我去买东西”。",explainEn:"For telling someone to do something use 让/叫: 妈妈让我去买东西."},{q:"翻译：This song makes me miss home.",a:"这首歌让我很想家。",instr:"翻译",instrEn:"Translate",body:"This song makes me miss home."}],note:"“使”较书面；“叫、让”更口语。三者都可以表示“使某人/某物产生某种结果”。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"shǐ / jiào / ràng + person/thing + predicate = make / let sb do sth",noteEn:'使 is more formal; 叫/让 are colloquial; all mean "cause someone/something to…".',typeEn:"Pivotal sentence"}]},{num:20,title:"我被他影响了",points:[{id:"3.20.1",name:"“被”字句表示被动",pinyin:"bèi zì jù",type:"被动句",explainEn:"Use 被 to say the subject receives an action: “be done by…”.",structure:"A + 被 + B + 动词 + 其他成分",examples:[{zh:"我的苹果被弟弟吃了。",en:"My apple was eaten by my younger brother.",py:"Wǒ de píngguǒ bèi dìdi chī le."},{zh:"门被风打开了。",en:"The door was opened by the wind.",py:"Mén bèi fēng dǎkāi le."},{zh:"我的书被他拿走了。",en:"My book was taken away by him.",py:"Wǒ de shū bèi tā ná zǒu le."}],exercises:[{kind:"choice",q:"我的自行车___人骑走了。",instr:"辨析",instrEn:"Pick the right one",body:"我的自行车___人骑走了。",options:["把","对","从","被"],answer:3,explain:"自行车是受动作的一方，用“被”引出做动作的人；“把”的前面要是做动作的人。",explainEn:"The bike receives the action, so 被 introduces the doer; with 把, the doer would come first."},{kind:"choice",q:"我的蛋糕被弟弟___。",instr:"完成",instrEn:"Complete the sentence",body:"我的蛋糕被弟弟___。",options:["吃了","吃","在吃","吃着"],answer:0,explain:"“被”字句的动词后面要有其他成分，比如“了”或补语，不能只有一个动词。",explainEn:"In a 被 sentence the verb needs something after it, such as 了 or a complement."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["门被风关上了。","我的手机被妹妹拿走了。","这本书被他没借走。","我的作业被狗吃了。"],answer:2,explain:"否定词要放在“被”前面，应说“这本书没被他借走”。",explainEn:"The negative goes before 被: 这本书没被他借走."},{q:"翻译：The door was opened by my little brother.",a:"门被弟弟打开了。",instr:"翻译",instrEn:"Translate",body:"The door was opened by my little brother."}],note:"HSK3先掌握最基本结构；否定通常用“没（有）被……”。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"A + bèi + B + Verb + other elements = A is … by B (passive)",noteEn:"Learn the basic pattern first; the negative is usually 没(有)被….",typeEn:"Passive"},{id:"3.20.2",name:"“只有……，才……”表示必要条件",pinyin:"zhǐyǒu ... cái ...",type:"条件复句",explainEn:"Use 只有…才… to mean “only if… then…”. The first condition is necessary.",structure:"只有 + 条件，才 + 结果",examples:[{zh:"只有多练习，汉语才会进步。",en:"Only with more practice will your Chinese improve.",py:"Zhǐyǒu duō liànxí, Hànyǔ cái huì jìnbù."},{zh:"只有有票，才能进去。",en:"Only if you have a ticket can you go in.",py:"Zhǐyǒu yǒu piào, cái néng jìnqu."},{zh:"只有周末，我才有时间运动。",en:"Only on weekends do I have time to exercise.",py:"Zhǐyǒu zhōumò, wǒ cái yǒu shíjiān yùndòng."}],exercises:[{kind:"choice",q:"只有多说，你的汉语___能说得好。",instr:"辨析",instrEn:"Pick the right one",body:"只有多说，你的汉语___能说得好。",options:["就","都","才","也"],answer:2,explain:"“只有”和“才”搭配，表示一定要有这个条件；“就”和“只要”搭配。",explainEn:"只有 pairs with 才 (a necessary condition); 就 pairs with 只要."},{kind:"choice",q:"只有你去请他，___",instr:"完成",instrEn:"Complete the sentence",body:"只有你去请他，___",options:["他就不来。","他也会来。","谁都会来。","他才会来。"],answer:3,explain:"“只有”表示必须有这个条件，后面用“才”说结果。",explainEn:"只有 marks the only condition, and the result takes 才."},{kind:"choice",q:"下面哪一句有错？",instr:"找错",instrEn:"Find the wrong sentence",body:"下面哪一句有错？",options:["只有周末他才有空。","只有多看多写，才能记住汉字。","只有下雨，我们就不出去。","只有你来，我才放心。"],answer:2,explain:"“只有”要和“才”搭配，这里可以改为“如果下雨，我们就不出去”。",explainEn:"只有 must pair with 才; here say 如果下雨，我们就不出去."},{q:"翻译：Only if you go there will you know.",a:"只有你去了，才会知道。",instr:"翻译",instrEn:"Translate",body:"Only if you go there will you know."}],note:"“只要……就……”=条件够了就行；“只有……才……”=这个条件是必须的。",source:"https://jyangkul.net/HSK/HSK%203/HSK%20standard%20course%203%20pdf.pdf",structureEn:"zhǐyǒu + condition, cái + result = only if …, then …",noteEn:"只要…就… = enough condition; 只有…才… = a necessary condition.",typeEn:"Conditional"}]}],i={series:e,unit:3,lessons:n};export{i as default,n as lessons,e as series,t as unit};
